insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('morning-intention-card', 'Morning Intention Card', 'worksheet'::resource_kind, 'A small card where a client names one intention, one obstacle and one kind action for the day.', 'Use it to help a client start the day with a clear, modest aim.', array['Adults']::text[], 'Five minutes daily', 'Have the client fill the card in session once, then daily at home. Keep the intention small and in their own words. In follow-up, ask what the obstacle looked like in real life and whether the kind action happened, without grading the day.', '[{"id": "f0", "type": "textarea", "label": "My intention for today"}, {"id": "f1", "type": "textarea", "label": "One thing that could get in the way"}, {"id": "f2", "type": "textarea", "label": "What I can do if it shows up"}, {"id": "f3", "type": "textarea", "label": "One kind thing I will do for myself or someone else"}]'::jsonb, array['routines', 'planning']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('week-in-review-reflection-page', 'Week in Review Reflection Page', 'worksheet'::resource_kind, 'A page for looking back over seven days at what went well, what was hard and what to carry forward.', 'Use it to give a client a steady way to reflect and set up the next week.', array['Adults']::text[], '20 minutes', 'Use it at the start of a session as a warm-up. Let the client read their answers aloud and notice patterns across days. Ask what they want to keep, change or let go of, and choose one carry-forward item together.', '[{"id": "f0", "type": "textarea", "label": "Something that went well this week"}, {"id": "f1", "type": "textarea", "label": "Something that was hard"}, {"id": "f2", "type": "textarea", "label": "What I learned about myself"}, {"id": "f3", "type": "textarea", "label": "What I want to carry into next week"}, {"id": "f4", "type": "textarea", "label": "What I want to leave behind"}]'::jsonb, array['weekly review', 'reflection']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('hard-talk-opening-line-planner', 'Hard Talk Opening Line Planner', 'worksheet'::resource_kind, 'A planning page for a difficult talk: the goal, the opening line, likely replies and a calm exit.', 'Use it to help a client prepare words and a plan before a hard conversation.', array['Adults']::text[], '25 minutes', 'Fill the page in together, then rehearse the opening line aloud and take the other person''s part for a round. Clients often over-script, so keep each reply to one sentence. Agree on a calm exit line they can use if the talk goes sideways.', '[{"id": "f0", "type": "textarea", "label": "Who I need to talk to and what I hope for"}, {"id": "f1", "type": "textarea", "label": "My opening line"}, {"id": "f2", "type": "textarea", "label": "What they might say back"}, {"id": "f3", "type": "textarea", "label": "How I could answer"}, {"id": "f4", "type": "textarea", "label": "What I will say if I need to pause or leave"}]'::jsonb, array['communication', 'planning']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('comfort-zone-edge-notes', 'Comfort Zone Edge Notes', 'worksheet'::resource_kind, 'A page for marking what feels easy, what stretches the client and what feels too much right now.', 'Use it to help a client pick a stretch that is challenging without being overwhelming.', array['Adults']::text[], '20 minutes', 'Draw three rings with the client and sort real situations into them. The middle ring is where most practice happens. Ask how they will know a step is the right size, and leave the choice of the next step with them.', '[{"id": "f0", "type": "textarea", "label": "Things that feel easy for me"}, {"id": "f1", "type": "textarea", "label": "Things that stretch me a little"}, {"id": "f2", "type": "textarea", "label": "Things that feel too much right now"}, {"id": "f3", "type": "textarea", "label": "The stretch I will try this week"}, {"id": "f4", "type": "textarea", "label": "What will help me stay with it"}]'::jsonb, array['growth', 'planning']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('gratitude-specifics-log', 'Gratitude Specifics Log', 'worksheet'::resource_kind, 'A short daily log that asks for one specific thing, why it mattered and who or what made it possible.', 'Use it to help a client notice small, concrete good moments in a week.', array['Adults', 'Teens']::text[], 'Five minutes daily for a week', 'Specific beats general, so push gently for detail: not ''my family'' but ''my sister texted me a photo of the dog.'' If a client finds the task flat, shrink it to a single line a day. Review the week together and notice which kinds of moments recur.', '[{"id": "f0", "type": "textarea", "label": "Something good that happened today, in detail"}, {"id": "f1", "type": "textarea", "label": "Why it mattered to me"}, {"id": "f2", "type": "textarea", "label": "Who or what made it possible"}, {"id": "f3", "type": "textarea", "label": "How I felt in my body when I noticed it"}]'::jsonb, array['gratitude', 'self-monitoring']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('cognitive-continuum-line', 'Cognitive Continuum Line', 'cbt'::resource_kind, 'A drawn line from zero to one hundred for placing a black-and-white thought between its extremes.', 'Use it to help a client loosen all-or-nothing thinking by finding the gray in between.', array['Adults', 'Teens']::text[], '20 minutes', 'Draw the line on paper and have the client name what sits at each end using real people or events. Then place the current situation. Many clients move the mark a few points once the ends are concrete. Ask what a more balanced sentence would be.', '[{"id": "f0", "type": "textarea", "label": "The all-or-nothing thought I am having"}, {"id": "f1", "type": "textarea", "label": "What sits at zero on the line"}, {"id": "f2", "type": "textarea", "label": "What sits at one hundred"}, {"id": "f3", "type": "textarea", "label": "Where my situation really falls, and why"}, {"id": "f4", "type": "textarea", "label": "A more balanced way to say it"}]'::jsonb, array['core CBT', 'thinking traps']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('belief-advantages-and-disadvantages-grid', 'Belief Advantages and Disadvantages Grid', 'cbt'::resource_kind, 'A four-box grid weighing what a belief gives the client and what it costs them.', 'Use it to help a client examine what a long-held belief does for and against them.', array['Adults']::text[], '30 minutes', 'Work through the boxes in order and take the advantages seriously, since the belief has usually served a purpose. Then ask whether a different belief could keep the advantages and drop some costs. Hold the pace so the client does not feel argued out of it.', '[{"id": "f0", "type": "textarea", "label": "The belief I want to look at"}, {"id": "f1", "type": "textarea", "label": "What this belief gives me"}, {"id": "f2", "type": "textarea", "label": "What this belief costs me"}, {"id": "f3", "type": "textarea", "label": "A different belief that might fit better"}, {"id": "f4", "type": "textarea", "label": "One small action that fits the new belief"}]'::jsonb, array['core CBT', 'core beliefs']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('stepwise-task-ladder-with-ratings', 'Stepwise Task Ladder With Ratings', 'cbt'::resource_kind, 'A ladder that breaks a big, avoided task into small steps with a rating for each rung.', 'Use it to help a client approach a large task one manageable step at a time.', array['Adults', 'Teens']::text[], '30 minutes', 'Start with the finished task at the top and work down to a first rung the client is nearly certain they can do. Ask for a difficulty rating on each rung and revise any that jump too far. Review after each step and let the client decide when to climb.', '[{"id": "f0", "type": "textarea", "label": "The task I have been putting off"}, {"id": "f1", "type": "textarea", "label": "The very first tiny step"}, {"id": "f2", "type": "textarea", "label": "The steps in between, from easiest to hardest"}, {"id": "f3", "type": "textarea", "label": "How hard each step feels, from zero to ten"}, {"id": "f4", "type": "textarea", "label": "How I will reward or acknowledge each step"}]'::jsonb, array['core CBT', 'planning', 'behavioral activation']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('seven-step-problem-solving-page', 'Seven-Step Problem Solving Page', 'cbt'::resource_kind, 'A seven-step page that moves from defining a problem to trying one solution and reviewing it.', 'Use it to give a client a repeatable way to work through a stuck problem.', array['Adults', 'Teens']::text[], '30 minutes', 'Take one real, solvable problem to practice on. Spend extra time on brainstorming without judging ideas, since clients tend to cross options off too early. Choose one solution together, set a time to try it and review what happened next session.', '[{"id": "f0", "type": "textarea", "label": "The problem, stated in one clear sentence"}, {"id": "f1", "type": "textarea", "label": "Every idea I can think of, even silly ones"}, {"id": "f2", "type": "textarea", "label": "The pros and cons of my top two ideas"}, {"id": "f3", "type": "textarea", "label": "The one I will try"}, {"id": "f4", "type": "textarea", "label": "When and how I will try it"}, {"id": "f5", "type": "textarea", "label": "What happened, and what I would change"}]'::jsonb, array['core CBT', 'problem solving']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('behavioral-experiment-debrief-sheet', 'Behavioral Experiment Debrief Sheet', 'cbt'::resource_kind, 'A sheet for looking back on an experiment: what was predicted, what happened and what it suggests.', 'Use it to help a client learn from a test of a belief, whatever the result.', array['Adults', 'Teens']::text[], '20 minutes', 'Complete it right after the experiment while details are fresh. Compare the prediction with what actually happened and ask what else could explain the result. Avoid steering toward a particular lesson. A surprising result is useful even when the client is unsure what to make of it.', '[{"id": "f0", "type": "textarea", "label": "What I predicted would happen"}, {"id": "f1", "type": "textarea", "label": "What actually happened"}, {"id": "f2", "type": "textarea", "label": "What surprised me"}, {"id": "f3", "type": "textarea", "label": "Other explanations for what happened"}, {"id": "f4", "type": "textarea", "label": "What I want to try next"}]'::jsonb, array['core CBT', 'behavioral experiment']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('tug-of-war-with-a-monster-sketch', 'Tug of War With a Monster Sketch', 'act'::resource_kind, 'A drawing of a tug of war with a monster and a prompt to consider putting down the rope.', 'Use it to help a client see the cost of fighting an unwanted thought or feeling.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client draw themselves and a monster named for their struggle, with a rope between them and a pit in the middle. Ask what the tugging has cost. Then wonder aloud what dropping the rope would let their hands do. Let them draw that too.', '[{"id": "f0", "type": "textarea", "label": "The monster I have been fighting, named"}, {"id": "f1", "type": "textarea", "label": "What I have tried to win the tug of war"}, {"id": "f2", "type": "textarea", "label": "What the struggle has cost me"}, {"id": "f3", "type": "textarea", "label": "What my hands could do if I dropped the rope"}]'::jsonb, array['core ACT', 'willingness', 'metaphor']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('milk-milk-milk-word-repeat-trial', 'Milk Milk Milk Word Repeat Trial', 'act'::resource_kind, 'A playful trial of saying a word aloud many times to notice how its meaning loosens.', 'Use it to give a client a firsthand feel for how thoughts are made of words.', array['Adults', 'Teens', 'Groups']::text[], '10 minutes', 'Begin with a neutral word such as milk and repeat it aloud for a minute. Then try a word the client uses against themselves. Keep it light and stop if it feels like mockery of their pain. Ask what changed, and let them decide whether it helps.', '[{"id": "f0", "type": "textarea", "label": "The neutral word I tried"}, {"id": "f1", "type": "textarea", "label": "What happened to the word as I repeated it"}, {"id": "f2", "type": "textarea", "label": "The word or phrase I tried next"}, {"id": "f3", "type": "textarea", "label": "What I noticed when I said it many times"}, {"id": "f4", "type": "textarea", "label": "When I might use this"}]'::jsonb, array['core ACT', 'defusion']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('noticing-the-hook-log', 'Noticing the Hook Log', 'act'::resource_kind, 'A log for catching the moments a thought or feeling pulls the client away from what matters.', 'Use it to help a client spot hooks and choose what to do next.', array['Adults', 'Teens']::text[], 'One week', 'Introduce the idea of being hooked, then have the client log a few moments across the week. Review for patterns in hooks, such as criticism or fatigue. Ask what a values-guided response would have looked like, without blaming the times they got pulled.', '[{"id": "f0", "type": "textarea", "label": "What hooked me"}, {"id": "f1", "type": "textarea", "label": "What my mind said"}, {"id": "f2", "type": "textarea", "label": "What I did when I got hooked"}, {"id": "f3", "type": "textarea", "label": "What I would have done if I had unhooked"}, {"id": "f4", "type": "textarea", "label": "What matters to me here"}]'::jsonb, array['core ACT', 'values', 'self-monitoring']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('committed-action-mini-goals-sheet', 'Committed Action Mini-Goals Sheet', 'act'::resource_kind, 'A sheet that turns one value into three small goals with a time and a likely obstacle.', 'Use it to help a client move from knowing their values to taking small steps.', array['Adults']::text[], '25 minutes', 'Start with one value the client chose and turn it into goals they could finish within a week. Make each one specific enough to picture: when, where, how long. Name the obstacle that will most likely show up and plan a willing response.', '[{"id": "f0", "type": "textarea", "label": "A value I want to move toward"}, {"id": "f1", "type": "textarea", "label": "Three small actions that fit it"}, {"id": "f2", "type": "textarea", "label": "When and where I will do each one"}, {"id": "f3", "type": "textarea", "label": "The obstacle most likely to show up"}, {"id": "f4", "type": "textarea", "label": "How I will respond if it does"}]'::jsonb, array['core ACT', 'committed action', 'values']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('four-quadrant-act-matrix-page', 'Four-Quadrant ACT Matrix Page', 'act'::resource_kind, 'A two-by-two page sorting what the client moves toward, what hooks them and what they notice inside.', 'Use it to give a client a simple map of away moves, toward moves and inner experience.', array['Adults', 'Teens']::text[], '30 minutes', 'Draw the matrix with the client and fill in the lower half first, what they notice inside and what they do to get away from it. Then fill in who and what matter to them. Look together at which moves go toward the right side and which away.', '[{"id": "f0", "type": "textarea", "label": "Who and what matter to me"}, {"id": "f1", "type": "textarea", "label": "What shows up inside that gets in the way"}, {"id": "f2", "type": "textarea", "label": "What I do to get away from those feelings"}, {"id": "f3", "type": "textarea", "label": "What I could do to move toward what matters"}]'::jsonb, array['core ACT', 'values', 'avoidance']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('behavior-chain-mapping-sheet', 'Behavior Chain Mapping Sheet', 'dbt'::resource_kind, 'A step-by-step chain from a prompting event through thoughts, feelings and actions to the outcome.', 'Use it to help a client see the links in a pattern and where a skill could fit.', array['Adults', 'Teens']::text[], '40 minutes', 'Map one recent moment in small steps, and keep the tone curious rather than critical. Mark the links where a different skill could have changed the chain. Complete it in session first, and use shorter chains for homework.', '[{"id": "f0", "type": "textarea", "label": "The event that set things off"}, {"id": "f1", "type": "textarea", "label": "Thoughts and feelings that came next"}, {"id": "f2", "type": "textarea", "label": "What I did, step by step"}, {"id": "f3", "type": "textarea", "label": "What happened afterward"}, {"id": "f4", "type": "textarea", "label": "A link where I could use a skill next time"}]'::jsonb, array['core DBT', 'self-monitoring', 'skills']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('improve-skills-idea-menu', 'IMPROVE Skills Idea Menu', 'dbt'::resource_kind, 'A menu built from the IMPROVE skills so a client can pick one for a hard moment.', 'Use it to help a client get through a painful moment without making it worse.', array['Adults', 'Teens']::text[], '20 minutes', 'Go through the letters one by one and have the client write an idea of their own for each. Rehearse one in the room. Remind them that these skills help them get through a moment and do not solve the underlying problem.', '[{"id": "f0", "type": "textarea", "label": "Imagery that helps me"}, {"id": "f1", "type": "textarea", "label": "A meaning I can find in this moment"}, {"id": "f2", "type": "textarea", "label": "A way to pray, breathe or settle"}, {"id": "f3", "type": "textarea", "label": "A way to relax my body"}, {"id": "f4", "type": "textarea", "label": "One thing I can do at a time"}, {"id": "f5", "type": "textarea", "label": "A short vacation I can give myself"}, {"id": "f6", "type": "textarea", "label": "Encouragement I can say to myself"}]'::jsonb, array['core DBT', 'distress tolerance']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('emotion-mind-and-reasonable-mind-sort', 'Emotion Mind and Reasonable Mind Sort', 'dbt'::resource_kind, 'A sorting page that places a client''s recent thoughts and urges under emotion, reasonable or wise mind.', 'Use it to help a client tell which state is driving their choices.', array['Adults', 'Teens']::text[], '20 minutes', 'Take three recent decisions and sort the thoughts behind each. Ask what the client would have done from each state. No state is bad; the point is noticing which one is steering. Practice finding the overlap that wise mind uses.', '[{"id": "f0", "type": "textarea", "label": "A recent decision or reaction"}, {"id": "f1", "type": "textarea", "label": "What emotion mind said"}, {"id": "f2", "type": "textarea", "label": "What reasonable mind said"}, {"id": "f3", "type": "textarea", "label": "What wise mind might say"}, {"id": "f4", "type": "textarea", "label": "What I would like to do next time"}]'::jsonb, array['core DBT', 'emotion regulation']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('both-and-dialectic-statements', 'Both-And Dialectic Statements', 'dbt'::resource_kind, 'A page for rewriting either-or sentences into both-and ones that hold two truths.', 'Use it to help a client loosen rigid thinking by holding two things at once.', array['Adults', 'Teens']::text[], '15 minutes', 'Start with simple examples such as ''I am tired and I can keep going.'' Then have the client rewrite a sentence from their own week. Watch for ''but'' creeping back in and invite ''and.'' Share a few aloud so the practice feels shared.', '[{"id": "f0", "type": "textarea", "label": "An either-or thought I had this week"}, {"id": "f1", "type": "textarea", "label": "The two sides inside it"}, {"id": "f2", "type": "textarea", "label": "My both-and version"}, {"id": "f3", "type": "textarea", "label": "How it feels to say the both-and version"}]'::jsonb, array['core DBT', 'dialectics']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('mindfulness-what-and-how-skills-log', 'Mindfulness What and How Skills Log', 'dbt'::resource_kind, 'A log that records which what skill and how skill the client practiced and what they noticed.', 'Use it to help a client build a habit of practicing core mindfulness skills.', array['Adults', 'Teens']::text[], 'One week', 'Review the what skills (observe, describe, participate) and the how skills (nonjudgmentally, one-mindfully, effectively) together. Ask for one short practice a day. In follow-up, focus on what the client noticed instead of how well they did.', '[{"id": "f0", "type": "textarea", "label": "The skill I practiced"}, {"id": "f1", "type": "textarea", "label": "What I was doing while I practiced"}, {"id": "f2", "type": "textarea", "label": "What I noticed"}, {"id": "f3", "type": "textarea", "label": "What got in the way"}, {"id": "f4", "type": "textarea", "label": "What I will practice tomorrow"}]'::jsonb, array['core DBT', 'mindfulness', 'skills']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('dreams-within-conflict-talk', 'Dreams Within Conflict Talk', 'couples'::resource_kind, 'A guide for each partner to share the dream or story underneath a recurring disagreement.', 'Use it to help partners hear what a stuck conflict means to each of them.', array['Couples']::text[], '50 minutes', 'Choose one gridlocked topic. Each partner takes a turn as speaker while the other listens and asks curious questions. The listener does not fix or defend. Each partner fills in their own half before the conversation and shares only what they choose.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the issue and what it means to me"}, {"id": "f1", "type": "textarea", "label": "Partner A: the dream or value underneath it"}, {"id": "f2", "type": "textarea", "label": "Partner B: the issue and what it means to me"}, {"id": "f3", "type": "textarea", "label": "Partner B: the dream or value underneath it"}, {"id": "f4", "type": "textarea", "label": "Something we each can honor without agreeing on everything"}]'::jsonb, array['Gottman', 'conflict', 'couples']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('outside-stress-listening-guide', 'Outside Stress Listening Guide', 'couples'::resource_kind, 'A guide for partners to take turns talking about outside stress while the other simply supports.', 'Use it to help partners turn toward each other about stress that is not about them.', array['Couples']::text[], '30 minutes', 'Each partner gets about fifteen minutes as speaker. The listener''s job is to understand, not to fix. Coach them to ask open questions and to show they are on the speaker''s side. Watch for advice slipping in and name it kindly.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what is stressing me outside our relationship"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I need from my partner right now"}, {"id": "f2", "type": "textarea", "label": "Partner B: what is stressing me outside our relationship"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I need from my partner right now"}, {"id": "f4", "type": "textarea", "label": "What we noticed about listening to each other"}]'::jsonb, array['Gottman', 'connection', 'couples']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('love-map-question-deck', 'Love Map Question Deck', 'couples'::resource_kind, 'A set of open questions partners ask each other to learn and update what they know about each other.', 'Use it to help partners rebuild curiosity about each other''s inner world.', array['Couples']::text[], '30 minutes', 'Have the partners pick cards in turn and answer for themselves first. Notice which questions surprise them. If a topic is tender, let either partner pass. Ask what they want to remember about each other this week.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a question I asked and what I learned"}, {"id": "f1", "type": "textarea", "label": "Partner B: a question I asked and what I learned"}, {"id": "f2", "type": "textarea", "label": "Something that surprised us"}, {"id": "f3", "type": "textarea", "label": "A new thing we want to know about each other"}]'::jsonb, array['Gottman', 'connection', 'couples']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('bids-tally-for-turning-toward', 'Bids Tally for Turning Toward', 'couples'::resource_kind, 'A tally sheet where partners notice small bids for connection and how they answered.', 'Use it to help partners notice and respond to everyday bids for attention.', array['Couples']::text[], 'One week', 'Explain a bid as any small attempt to connect, such as a comment or a touch. Each partner tallies their own bids and their responses during the week. Review without scorekeeping against each other and pick one bid to answer more often.', '[{"id": "f0", "type": "textarea", "label": "Partner A: bids I noticed this week"}, {"id": "f1", "type": "textarea", "label": "Partner B: bids I noticed this week"}, {"id": "f2", "type": "textarea", "label": "A bid I missed and what I wish I had done"}, {"id": "f3", "type": "textarea", "label": "A bid answered well and how it felt"}]'::jsonb, array['Gottman', 'communication', 'couples']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('aftermath-of-a-fight-review', 'Aftermath of a Fight Review', 'couples'::resource_kind, 'A guided review for after an argument: what each felt, what was heard and what each wants to own.', 'Use it to help partners learn from a rupture and repair after it.', array['Couples']::text[], '40 minutes', 'Wait until both partners are calm. Each partner shares their own feelings and perceptions in turn while the other listens without arguing the facts. Close with what each owns and one change for next time. Stop if either partner becomes flooded.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I felt and what I needed"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I felt and what I needed"}, {"id": "f2", "type": "textarea", "label": "What each of us can own"}, {"id": "f3", "type": "textarea", "label": "What we will try next time"}, {"id": "f4", "type": "textarea", "label": "How we will reconnect now"}]'::jsonb, array['Gottman', 'repair', 'couples']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('worry-stone-painting-craft', 'Worry Stone Painting Craft', 'kids'::resource_kind, 'A craft where a child paints a smooth stone to hold during worried moments.', 'Use it to give a child a calming object they made themselves.', array['Children']::text[], '30 minutes', 'Let the child pick stone and colors and talk about what a worry stone could do. Show how to rub it and breathe slowly. Afterward, give the parent the idea to keep a basket of stones at home and to practice the breathing with their child.', '[{"id": "f0", "type": "textarea", "label": "What I painted on my stone"}, {"id": "f1", "type": "textarea", "label": "When I might hold it"}, {"id": "f2", "type": "textarea", "label": "What I can do while I hold it"}, {"id": "f3", "type": "textarea", "label": "A grown-up who can help me remember"}]'::jsonb, array['children', 'art', 'coping skills']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('kindness-coupons-booklet', 'Kindness Coupons Booklet', 'kids'::resource_kind, 'A booklet of coupons a child decorates and gives to family members for acts of kindness.', 'Use it to help a child practice noticing and doing kind things.', array['Children']::text[], '30 minutes', 'The child cuts, folds and decorates a small booklet and writes or draws kind acts on each coupon. The parent chooses one coupon to redeem at home and says what they enjoyed. Keep the focus on joy and connection, not on being good.', '[{"id": "f0", "type": "textarea", "label": "A kind thing I can do for someone at home"}, {"id": "f1", "type": "textarea", "label": "A kind thing I can do at school"}, {"id": "f2", "type": "textarea", "label": "A kind thing someone can do for me"}, {"id": "f3", "type": "textarea", "label": "Who I will give my first coupon to"}]'::jsonb, array['children', 'kindness', 'family']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('cardboard-calm-castle-build', 'Cardboard Calm Castle Build', 'kids'::resource_kind, 'A build-it project where a child makes a cozy cardboard castle for calming down.', 'Use it to help a child make a quiet place and a plan for using it.', array['Children']::text[], '45 minutes', 'The child builds a small castle from a box and decorates it with calming items of their choice. Practice going in, taking slow breaths and coming out. The parent agrees not to send them there as a punishment and shows how to offer it with a gentle invitation.', '[{"id": "f0", "type": "textarea", "label": "What I put in my calm castle"}, {"id": "f1", "type": "textarea", "label": "How my body feels inside it"}, {"id": "f2", "type": "textarea", "label": "What I can do there"}, {"id": "f3", "type": "textarea", "label": "How I will tell my grown-up I need it"}]'::jsonb, array['children', 'play', 'regulation']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('emotion-monster-puppet-craft', 'Emotion Monster Puppet Craft', 'kids'::resource_kind, 'A puppet craft where a child makes a monster with a face for a feeling and gives it a voice.', 'Use it to help a child name a feeling and talk about it through a puppet.', array['Children']::text[], '40 minutes', 'The child makes a puppet from a paper bag or sock and picks a feeling for it. Play short scenes where the monster says what it needs. Follow the child''s lead. The parent practices answering the puppet kindly and not fixing the feeling.', '[{"id": "f0", "type": "textarea", "label": "The feeling my monster has"}, {"id": "f1", "type": "textarea", "label": "What makes my monster feel this way"}, {"id": "f2", "type": "textarea", "label": "What my monster needs"}, {"id": "f3", "type": "textarea", "label": "How my monster can ask for help"}]'::jsonb, array['children', 'play', 'emotion identification']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('bubble-breathing-play-plan', 'Bubble Breathing Play Plan', 'kids'::resource_kind, 'A play plan using bubbles to practice slow, steady breathing.', 'Use it to teach a child to slow their breath through play.', array['Children']::text[], '20 minutes', 'Blow bubbles together and show that a slow breath makes big, steady bubbles while a fast one pops them. Then practice pretend bubbles with no wand. The parent learns the game and offers it at calm times first so it is familiar when needed.', '[{"id": "f0", "type": "textarea", "label": "How my body feels when I blow slowly"}, {"id": "f1", "type": "textarea", "label": "What happens to the bubbles when I rush"}, {"id": "f2", "type": "textarea", "label": "A time I could blow pretend bubbles"}, {"id": "f3", "type": "textarea", "label": "Who can blow bubbles with me"}]'::jsonb, array['children', 'play', 'regulation']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('values-bidding-table-game', 'Values Bidding Table Game', 'game'::resource_kind, 'A group game in which players bid play money on values and then talk about their choices.', 'Use it to help players discover what they prize by choosing what to spend on.', array['Teens', 'Adults', 'Groups']::text[], '45 minutes', 'Give each player the same amount of play money and a list of values to bid on. Run each round briefly. In the debrief, ask what they bid on, what they let go and what it felt like to choose. No bid is right, and players may pass.', '[{"id": "f0", "type": "textarea", "label": "The values I bid on"}, {"id": "f1", "type": "textarea", "label": "One I wanted but did not get"}, {"id": "f2", "type": "textarea", "label": "What surprised me about my choices"}, {"id": "f3", "type": "textarea", "label": "One way I can honor a value this week"}]'::jsonb, array['values', 'group', 'play']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('thought-or-fact-buzzer-round', 'Thought or Fact Buzzer Round', 'game'::resource_kind, 'A quick team game in which players buzz in to label statements as thoughts, facts or both.', 'Use it to help players practice separating thoughts from facts.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Read a mix of statements aloud. Teams take turns buzzing in to say thought or fact and why. Include a few that are tricky. In the debrief, invite players to share one thought of their own they can now sort out.', '[{"id": "f0", "type": "textarea", "label": "A statement that was hard to sort"}, {"id": "f1", "type": "textarea", "label": "A thought of mine I treat as a fact"}, {"id": "f2", "type": "textarea", "label": "How I can check a thought"}, {"id": "f3", "type": "textarea", "label": "What I will do next time I notice it"}]'::jsonb, array['thinking traps', 'group', 'play']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('skill-memory-match-game', 'Skill Memory Match Game', 'game'::resource_kind, 'A card-matching game that pairs a hard situation with a coping skill that fits.', 'Use it to help players link everyday problems with skills they can use.', array['Children', 'Teens', 'Groups']::text[], '30 minutes', 'Make two sets of cards, one of situations and one of skills. Players take turns flipping two cards and explain how the skill could help if they find a match. Players may suggest their own skills. In the debrief, ask which skills they would use.', '[{"id": "f0", "type": "textarea", "label": "A match I made and why it fits"}, {"id": "f1", "type": "textarea", "label": "A skill I have used before"}, {"id": "f2", "type": "textarea", "label": "A skill I want to try"}, {"id": "f3", "type": "textarea", "label": "A situation I want to be ready for"}]'::jsonb, array['coping skills', 'group', 'play']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('pass-the-problem-story-circle', 'Pass the Problem Story Circle', 'game'::resource_kind, 'A group story game where each player adds a step to help a character solve a problem.', 'Use it to help players practice problem solving and perspective taking.', array['Children', 'Teens', 'Groups']::text[], '30 minutes', 'Start a story with a character facing a problem. Each player adds one sentence in turn about what the character feels or does. After a round, discuss what helped. The leader keeps the problem light and avoids stories that mirror a player''s situation.', '[{"id": "f0", "type": "textarea", "label": "The character''s problem in my words"}, {"id": "f1", "type": "textarea", "label": "What I added to the story"}, {"id": "f2", "type": "textarea", "label": "The idea I liked best from someone else"}, {"id": "f3", "type": "textarea", "label": "What I could try if I had that problem"}]'::jsonb, array['problem solving', 'group', 'play']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('zone-hop-feelings-floor-game', 'Zone Hop Feelings Floor Game', 'game'::resource_kind, 'A floor game where players hop to a colored zone that matches a feeling and share a time they felt it.', 'Use it to help players name feelings and notice how they change.', array['Children', 'Groups']::text[], '30 minutes', 'Lay out four colored sheets for different feeling zones. Call out a scenario and have players hop to the zone that fits. Invite them to share, but let them pass. Close by asking each player what helps them move between zones.', '[{"id": "f0", "type": "textarea", "label": "A zone I landed on and why"}, {"id": "f1", "type": "textarea", "label": "A time I felt that way"}, {"id": "f2", "type": "textarea", "label": "What helps me change zones"}, {"id": "f3", "type": "textarea", "label": "What I will tell a grown-up when I am in a hard zone"}]'::jsonb, array['emotion identification', 'children', 'play']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('window-of-steadiness-daily-check', 'Window of Steadiness Daily Check', 'worksheet'::resource_kind, 'A daily check of how settled the client''s body feels and which supports help them stay in range.', 'Use it to help a client notice when they are steady and what helps them stay there.', array['Adults']::text[], 'Five minutes daily', 'This is a stabilizing check-in, not a place to describe what happened. Have the client rate steadiness and note what supports helped. Review it together for patterns in the day. If numbers climb, shift to grounding in the session.', '[{"id": "f0", "type": "textarea", "label": "How settled my body felt today, zero to ten"}, {"id": "f1", "type": "textarea", "label": "What helped me stay steady"}, {"id": "f2", "type": "textarea", "label": "What nudged me out of my steady range"}, {"id": "f3", "type": "textarea", "label": "One support I will lean on tomorrow"}]'::jsonb, array['PTSD and trauma', 'grounding', 'self-monitoring']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('safety-versus-reminder-thought-check', 'Safety Versus Reminder Thought Check', 'cbt'::resource_kind, 'A thought check that separates a reminder of the past from danger in the present moment.', 'Use it to help a client tell a reminder apart from what is happening now.', array['Adults']::text[], '25 minutes', 'Keep this in the present. Ask the client to name what in the room tells them they are safe now, and to note the reminder without retelling events. Stop and ground if the client drifts into details. Complete it together before sending it home.', '[{"id": "f0", "type": "textarea", "label": "What reminded me today, in a few words"}, {"id": "f1", "type": "textarea", "label": "What my mind told me it meant"}, {"id": "f2", "type": "textarea", "label": "What tells me I am safe right now"}, {"id": "f3", "type": "textarea", "label": "A kinder thought I can hold right now"}]'::jsonb, array['PTSD and trauma', 'core CBT', 'safety']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('making-room-while-staying-oriented-practice', 'Making Room While Staying Oriented Practice', 'act'::resource_kind, 'A short practice for noticing a memory or feeling without pushing it away, paced by the client.', 'Use it to help a client make a little room for hard inner experience while staying present.', array['Adults']::text[], '20 minutes', 'Frame this as noticing, not retelling. The client keeps eyes open and stays oriented to the room, naming five things they see. Stop at any sign of overwhelm. Make sure they leave grounded and agree on what support is available between sessions.', '[{"id": "f0", "type": "textarea", "label": "Where I felt the reminder in my body"}, {"id": "f1", "type": "textarea", "label": "What I did to make room for it"}, {"id": "f2", "type": "textarea", "label": "What I saw in the room to stay present"}, {"id": "f3", "type": "textarea", "label": "What I want my life to be about"}]'::jsonb, array['PTSD and trauma', 'core ACT', 'willingness']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('self-soothing-senses-plan-for-trauma-reminders', 'Self-Soothing Senses Plan for Trauma Reminders', 'dbt'::resource_kind, 'A plan matching each of the five senses with a soothing item for moments after a reminder.', 'Use it to help a client prepare calming steps for after a reminder shows up.', array['Adults', 'Teens']::text[], '25 minutes', 'Build the plan in a calm moment and try each sense in session. Choose items that feel safe and pleasant to the client, which can differ from what the clinician expects. Help them place the plan where they can find it quickly. If risk comes up, use 988 (call or text) and complete safety planning in session.', '[{"id": "f0", "type": "textarea", "label": "Something I can see that calms me"}, {"id": "f1", "type": "textarea", "label": "A sound that settles me"}, {"id": "f2", "type": "textarea", "label": "A scent that feels safe"}, {"id": "f3", "type": "textarea", "label": "A taste or texture that comforts me"}, {"id": "f4", "type": "textarea", "label": "A person or place I can go to, or 988 (call or text) if I feel unsafe"}]'::jsonb, array['PTSD and trauma', 'self-soothing', 'distress tolerance']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('grounding-card-draw-round', 'Grounding Card Draw Round', 'game'::resource_kind, 'A card game with grounding prompts that players draw and try one at a time.', 'Use it to help players practice grounding in a low-pressure group setting.', array['Adults', 'Teens', 'Groups']::text[], '30 minutes', 'Make cards with simple grounding prompts such as naming colors or feeling feet on the floor. Players draw a card, try it and say how it felt. They can pass. Keep it light and present-focused. In the debrief, ask which prompts to keep.', '[{"id": "f0", "type": "textarea", "label": "A card I drew and tried"}, {"id": "f1", "type": "textarea", "label": "What I noticed in my body"}, {"id": "f2", "type": "textarea", "label": "Which grounding step I liked best"}, {"id": "f3", "type": "textarea", "label": "When I will use it this week"}]'::jsonb, array['PTSD and trauma', 'grounding', 'group']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('anxiety-body-map-and-early-signals', 'Anxiety Body Map and Early Signals', 'worksheet'::resource_kind, 'A body outline where the client marks where anxiety shows up and which signals come first.', 'Use it to help a client spot early signals of anxiety so they can respond sooner.', array['Adults', 'Teens']::text[], '25 minutes', 'Hand over a body outline and have the client color where they feel anxiety and add words. Ask which sign comes first. Early signals give them a window to use a skill. Return to the map over a few sessions to see if it changes.', '[{"id": "f0", "type": "textarea", "label": "Where I feel anxiety in my body"}, {"id": "f1", "type": "textarea", "label": "The first sign I notice"}, {"id": "f2", "type": "textarea", "label": "What I do when I notice it"}, {"id": "f3", "type": "textarea", "label": "A skill I could try at that first sign"}]'::jsonb, array['anxiety', 'self-monitoring', 'body awareness']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('uncertainty-experiment-planner', 'Uncertainty Experiment Planner', 'cbt'::resource_kind, 'A planner for choosing a small uncertain situation, predicting what will happen and checking afterward.', 'Use it to help a client practice tolerating not knowing.', array['Adults']::text[], '30 minutes', 'Pick something small where the client usually seeks certainty. Write the prediction, run the experiment and compare. Keep the stakes low at first. Ask what the client learned about getting through not knowing, rather than about whether the prediction came true.', '[{"id": "f0", "type": "textarea", "label": "The uncertain situation I will try"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen"}, {"id": "f2", "type": "textarea", "label": "What I will do instead of seeking certainty"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "What I learned about not knowing"}]'::jsonb, array['anxiety', 'core CBT', 'uncertainty', 'behavioral experiment']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('anxiety-as-a-radio-practice', 'Anxiety as a Radio Practice', 'act'::resource_kind, 'A practice of letting anxiety play in the background like a radio while doing something that matters.', 'Use it to help a client act on values while anxiety is present.', array['Adults', 'Teens']::text[], '20 minutes', 'Describe anxiety as a radio that plays whether they like it or not. Have the client choose a small task that matters to them and do it with the radio on. Ask what they noticed about turning toward the task. Avoid promising the radio will go quiet.', '[{"id": "f0", "type": "textarea", "label": "What the radio was saying"}, {"id": "f1", "type": "textarea", "label": "The task I chose to do anyway"}, {"id": "f2", "type": "textarea", "label": "What I noticed while I did it"}, {"id": "f3", "type": "textarea", "label": "What matters to me about this task"}]'::jsonb, array['anxiety', 'core ACT', 'values', 'willingness']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('opposite-action-for-anxious-avoidance', 'Opposite Action for Anxious Avoidance', 'dbt'::resource_kind, 'A planner for picking an action opposite to an avoidance urge when the facts do not call for it.', 'Use it to help a client check whether avoidance fits the facts and try the opposite when it does not.', array['Adults', 'Teens']::text[], '25 minutes', 'Work through checking the facts first, because opposite action fits only when the emotion does not match the situation. Pick a small approach step and plan how to do it with full commitment. Review how it went at the next session.', '[{"id": "f0", "type": "textarea", "label": "The situation and the urge to avoid it"}, {"id": "f1", "type": "textarea", "label": "What the facts say about the danger"}, {"id": "f2", "type": "textarea", "label": "The opposite action I will try"}, {"id": "f3", "type": "textarea", "label": "How I will do it fully, including my body"}, {"id": "f4", "type": "textarea", "label": "What happened afterward"}]'::jsonb, array['anxiety', 'core DBT', 'opposite action', 'avoidance']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('partner-plan-for-anxious-evenings', 'Partner Plan for Anxious Evenings', 'couples'::resource_kind, 'A plan for partners to agree on how to be together when one of them is feeling anxious.', 'Use it to help partners support each other without taking over or avoiding.', array['Couples']::text[], '35 minutes', 'The partner who is anxious says what helps and what does not. The other says what they can offer. Watch for accommodation, such as always giving reassurance, and explore kinder alternatives. Review the plan after a week and adjust it together.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps me when I feel anxious"}, {"id": "f1", "type": "textarea", "label": "Partner A: what does not help"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I can offer"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I need for myself"}, {"id": "f4", "type": "textarea", "label": "What we will try this week"}]'::jsonb, array['anxiety', 'support', 'couples']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('tiny-steps-low-mood-planner', 'Tiny Steps Low Mood Planner', 'worksheet'::resource_kind, 'A planner that breaks a day into very small steps for days when everything feels heavy.', 'Use it to help a client take small steps on days when energy is low.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to pick actions so small they feel almost silly, such as opening the curtains. Let them choose the order. Review how the steps felt rather than how many were done. If thoughts of self-harm come up, talk it through in session and share 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "One tiny step for the morning"}, {"id": "f1", "type": "textarea", "label": "One tiny step for the afternoon"}, {"id": "f2", "type": "textarea", "label": "One tiny step for the evening"}, {"id": "f3", "type": "textarea", "label": "Who I can tell if the day feels too heavy, or 988 (call or text)"}]'::jsonb, array['depression', 'behavioral activation', 'planning']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('mood-lift-thought-swap-cards', 'Mood Lift Thought Swap Cards', 'cbt'::resource_kind, 'A set of cards pairing low-mood thoughts with kinder, believable alternatives.', 'Use it to help a client practice finding a gentler thought they can believe.', array['Adults', 'Teens']::text[], '25 minutes', 'Write real thoughts on one side of each card and alternatives on the other. Aim for believable alternatives, not cheerful ones. Ask the client to rate how much they believe each. Keep the cards where they can use them.', '[{"id": "f0", "type": "textarea", "label": "A heavy thought I have often"}, {"id": "f1", "type": "textarea", "label": "How much I believe it, zero to one hundred"}, {"id": "f2", "type": "textarea", "label": "A kinder thought that feels possible"}, {"id": "f3", "type": "textarea", "label": "How much I believe that one, zero to one hundred"}]'::jsonb, array['depression', 'core CBT', 'automatic thoughts']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('values-at-low-energy-menu', 'Values at Low Energy Menu', 'act'::resource_kind, 'A menu of tiny actions that match each of a client''s values on days with little energy.', 'Use it to help a client stay connected to what matters even when energy is low.', array['Adults']::text[], '20 minutes', 'List three values with the client, then add tiny actions for each that take under five minutes. The point is contact with values, not accomplishment. Revisit the menu when the client is stuck and ask which item feels closest.', '[{"id": "f0", "type": "textarea", "label": "A value that matters to me"}, {"id": "f1", "type": "textarea", "label": "A five-minute action that fits it"}, {"id": "f2", "type": "textarea", "label": "A one-minute action that fits it"}, {"id": "f3", "type": "textarea", "label": "What I will pick on a low-energy day"}]'::jsonb, array['depression', 'core ACT', 'values', 'committed action']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('build-mastery-small-wins-log', 'Build Mastery Small Wins Log', 'dbt'::resource_kind, 'A log of small mastery activities done each day and how they felt afterward.', 'Use it to help a client collect evidence of ability through manageable tasks.', array['Adults', 'Teens']::text[], 'One week', 'Choose a task that is slightly challenging yet doable. Have the client record it and their mood afterward. Compare days over the week. Highlight any effort, even partial, and avoid rating success by size.', '[{"id": "f0", "type": "textarea", "label": "The mastery task I did"}, {"id": "f1", "type": "textarea", "label": "How hard it felt, zero to ten"}, {"id": "f2", "type": "textarea", "label": "How I felt afterward"}, {"id": "f3", "type": "textarea", "label": "What I will try tomorrow"}]'::jsonb, array['depression', 'core DBT', 'skills', 'self-monitoring']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('mood-weather-window-drawing', 'Mood Weather Window Drawing', 'kids'::resource_kind, 'A drawing activity where a child paints the weather outside a window to show how they feel inside.', 'Use it to help a child show feelings through weather and talk about what could shift it.', array['Children', 'Teens']::text[], '30 minutes', 'The child draws a window and paints today''s feeling weather. Ask what helps weather change, such as a walk or a hug. The parent learns to ask about the weather at home. If a child says they want to be dead or hurt themselves, follow your usual safety steps and share 988 (call or text) with the family.', '[{"id": "f0", "type": "textarea", "label": "The weather in my window today"}, {"id": "f1", "type": "textarea", "label": "What makes my weather change"}, {"id": "f2", "type": "textarea", "label": "What a grown-up can do on a stormy day"}, {"id": "f3", "type": "textarea", "label": "A person I can tell, or 988 (call or text) if I feel unsafe"}]'::jsonb, array['depression', 'children', 'art']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('visual-task-chunker', 'Visual Task Chunker', 'worksheet'::resource_kind, 'A page that splits one overwhelming task into short, visible chunks with a timer for each.', 'Use it to help a client start and keep going on a task that feels too big.', array['Adults', 'Teens']::text[], '20 minutes', 'Use a real task from the client''s week. Write chunks small enough to finish in ten to fifteen minutes and add a pause between them. Place the sheet where they can see it. Review which chunk sizes work best for them.', '[{"id": "f0", "type": "textarea", "label": "The task that feels too big"}, {"id": "f1", "type": "textarea", "label": "The first small chunk"}, {"id": "f2", "type": "textarea", "label": "The next chunks in order"}, {"id": "f3", "type": "textarea", "label": "How long each chunk should take"}, {"id": "f4", "type": "textarea", "label": "What I will do for a break between chunks"}]'::jsonb, array['ADHD', 'planning', 'routines']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('distraction-trigger-spotting-log', 'Distraction Trigger Spotting Log', 'cbt'::resource_kind, 'A log for noticing what pulls the client''s attention away and what they did next.', 'Use it to help a client spot common distractions and plan a response.', array['Adults', 'Teens']::text[], 'One week', 'Have the client log a few distractions per day with a brief note. Look for patterns in time of day, setting or kind of task. Plan one change to the environment and one response for the moment of noticing.', '[{"id": "f0", "type": "textarea", "label": "What I was doing when I got pulled away"}, {"id": "f1", "type": "textarea", "label": "What pulled me away"}, {"id": "f2", "type": "textarea", "label": "How long it took me to notice"}, {"id": "f3", "type": "textarea", "label": "What I did to come back"}, {"id": "f4", "type": "textarea", "label": "One change I could make to my space"}]'::jsonb, array['ADHD', 'core CBT', 'self-monitoring']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('values-before-motivation-page', 'Values Before Motivation Page', 'act'::resource_kind, 'A page for choosing an action because of what matters, not because the client feels like doing it.', 'Use it to help a client act on values when the urge to do something else is strong.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to name a task they want to do for a reason that matters to them. Practice noticing the pull toward something else and returning. Keep the task small and the language free of shame about distractibility.', '[{"id": "f0", "type": "textarea", "label": "A task I want to do and why it matters"}, {"id": "f1", "type": "textarea", "label": "What my mind says when I try to start"}, {"id": "f2", "type": "textarea", "label": "What I can do while that is there"}, {"id": "f3", "type": "textarea", "label": "How I will know I came back"}]'::jsonb, array['ADHD', 'core ACT', 'values', 'committed action']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('wise-mind-pause-before-acting-cards', 'Wise Mind Pause Before Acting Cards', 'dbt'::resource_kind, 'A card set prompting a short pause and a wise mind check before an impulsive action.', 'Use it to help a client build a brief pause into impulsive moments.', array['Adults', 'Teens']::text[], '20 minutes', 'Write the pause prompts on cards the client can keep close. Practice with a role play where they feel an impulse. Keep the pause short, such as one slow breath. Praise any pause, even if the impulse still wins.', '[{"id": "f0", "type": "textarea", "label": "A situation where I act on impulse"}, {"id": "f1", "type": "textarea", "label": "The pause I will try"}, {"id": "f2", "type": "textarea", "label": "What wise mind might say"}, {"id": "f3", "type": "textarea", "label": "What I did and how it felt"}]'::jsonb, array['ADHD', 'core DBT', 'regulation']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('beat-the-interruption-listening-game', 'Beat the Interruption Listening Game', 'game'::resource_kind, 'A listening game that practices waiting for a turn, holding a thought and responding.', 'Use it to help players practice waiting and listening in a group.', array['Children', 'Teens', 'Groups']::text[], '25 minutes', 'Players hold a talking object and share one sentence. Others listen and wait until it is passed to them. Add a notepad to jot a thought while waiting. In the debrief, ask what helped them wait and what made it hard.', '[{"id": "f0", "type": "textarea", "label": "What helped me wait for my turn"}, {"id": "f1", "type": "textarea", "label": "How I held my thought while waiting"}, {"id": "f2", "type": "textarea", "label": "What was hard about listening"}, {"id": "f3", "type": "textarea", "label": "What I will try in class or at home"}]'::jsonb, array['ADHD', 'group', 'play']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('urge-wave-notes', 'Urge Wave Notes', 'worksheet'::resource_kind, 'A short log of an urge to use a substance, how it rose and fell, and what the client did.', 'Use it to help a client notice that urges rise, peak and pass.', array['Adults']::text[], 'One week', 'Have the client note the time, the cue and the strength of each urge. Review how long it took to pass and what they did. Normalize that urges come and go. Use the notes to plan for the cue that shows up most.', '[{"id": "f0", "type": "textarea", "label": "When the urge started and what set it off"}, {"id": "f1", "type": "textarea", "label": "How strong it was, zero to ten"}, {"id": "f2", "type": "textarea", "label": "What I did while it was there"}, {"id": "f3", "type": "textarea", "label": "How strong it was an hour later"}, {"id": "f4", "type": "textarea", "label": "What I would like to try next time"}]'::jsonb, array['addiction', 'urges', 'self-monitoring']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('risky-moment-rehearsal-map', 'Risky Moment Rehearsal Map', 'cbt'::resource_kind, 'A plan for rehearsing a situation where substance use is likely, with thoughts and actions mapped out.', 'Use it to help a client prepare for a tough situation before it arrives.', array['Adults']::text[], '35 minutes', 'Pick a real situation the client expects within the week. Map the thoughts, urges and options, and then rehearse it aloud. Include who they can call. Review afterward and adjust the plan without judging how it went.', '[{"id": "f0", "type": "textarea", "label": "The situation I expect"}, {"id": "f1", "type": "textarea", "label": "The thoughts and urges likely to show up"}, {"id": "f2", "type": "textarea", "label": "Three things I could do"}, {"id": "f3", "type": "textarea", "label": "Who I can contact"}, {"id": "f4", "type": "textarea", "label": "What I will tell myself"}]'::jsonb, array['addiction', 'core CBT', 'urges', 'planning']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('riding-the-urge-toward-a-value', 'Riding the Urge Toward a Value', 'act'::resource_kind, 'A practice of noticing an urge as a wave while taking a step toward something that matters.', 'Use it to help a client make room for an urge while choosing a valued action.', array['Adults']::text[], '20 minutes', 'Guide the client to notice where the urge sits in the body without acting. Then ask what they would like to do with their time instead. Keep the wave image as an option, not a rule. Check in on how they got through.', '[{"id": "f0", "type": "textarea", "label": "Where I feel the urge in my body"}, {"id": "f1", "type": "textarea", "label": "What the urge says"}, {"id": "f2", "type": "textarea", "label": "What matters to me more"}, {"id": "f3", "type": "textarea", "label": "The step I took toward that"}]'::jsonb, array['addiction', 'core ACT', 'urges', 'values']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('alternate-rebellion-and-adaptive-denial-reset', 'Alternate Rebellion and Adaptive Denial Reset', 'dbt'::resource_kind, 'A page for noticing the pull to act on an urge and choosing between a skill and a delay.', 'Use it to help a client delay an urge and pick an adaptive next step.', array['Adults']::text[], '25 minutes', 'Describe the skills in plain language and ask the client for their own example. Practice delay in session by setting a timer. Add a contact list for the moments when delay is not enough. Review what worked.', '[{"id": "f0", "type": "textarea", "label": "The urge and what triggered it"}, {"id": "f1", "type": "textarea", "label": "How I can delay for ten minutes"}, {"id": "f2", "type": "textarea", "label": "What I can do during the delay"}, {"id": "f3", "type": "textarea", "label": "Who I can reach out to"}, {"id": "f4", "type": "textarea", "label": "What I will do when the timer ends"}]'::jsonb, array['addiction', 'core DBT', 'urges', 'distress tolerance']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('partner-support-without-monitoring-agreement', 'Partner Support Without Monitoring Agreement', 'couples'::resource_kind, 'A written agreement between partners about how to support a loved one''s change without monitoring them.', 'Use it to help partners agree on support that respects the person''s choices.', array['Couples']::text[], '40 minutes', 'Each partner says what they need. The partner in recovery says what support looks like and what feels like policing. Let them agree on check-ins and what to do if there is a slip. Review it in a few weeks.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what support looks like to me"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I worry about"}, {"id": "f2", "type": "textarea", "label": "What each of us will do and not do"}, {"id": "f3", "type": "textarea", "label": "How we will check in"}, {"id": "f4", "type": "textarea", "label": "What we will do if there is a setback"}]'::jsonb, array['addiction', 'support', 'couples']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('anger-early-warning-signs-card', 'Anger Early Warning Signs Card', 'worksheet'::resource_kind, 'A card where the client lists the body, thought and behavior signs that show up before anger peaks.', 'Use it to help a client catch anger early, when they have the most choice.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask for the first small sign, not the explosion. Many clients know the end but not the start. Add one pause option to each sign. Have them keep the card in a pocket or phone.', '[{"id": "f0", "type": "textarea", "label": "Signs in my body"}, {"id": "f1", "type": "textarea", "label": "Thoughts that show up"}, {"id": "f2", "type": "textarea", "label": "What I do when I am getting angry"}, {"id": "f3", "type": "textarea", "label": "What I can try at the first sign"}]'::jsonb, array['anger management', 'triggers', 'self-monitoring']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('hot-thought-and-cooler-thought-pairs', 'Hot Thought and Cooler Thought Pairs', 'cbt'::resource_kind, 'A set of paired thoughts: the angry thought in the moment and a cooler one that is still honest.', 'Use it to help a client find options between a heated thought and a different view.', array['Adults', 'Teens']::text[], '25 minutes', 'Collect real hot thoughts from the past week. The cooler thought must feel true, so help the client adjust. Practice saying both aloud. Ask what changes in their body with each one.', '[{"id": "f0", "type": "textarea", "label": "The hot thought I had"}, {"id": "f1", "type": "textarea", "label": "What I felt in my body"}, {"id": "f2", "type": "textarea", "label": "A cooler thought that still feels honest"}, {"id": "f3", "type": "textarea", "label": "What I would do with the cooler thought"}]'::jsonb, array['anger management', 'core CBT', 'automatic thoughts']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('what-my-anger-guards-reflection', 'What My Anger Guards Reflection', 'act'::resource_kind, 'A reflection on what a client''s anger is guarding and what they would choose to do about it.', 'Use it to help a client see what matters underneath anger.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what the anger is protecting, such as fairness, respect or safety. Explore what values sit under it. Then ask how they could stand up for that value without the cost they usually pay. Hold the anger as legitimate information.', '[{"id": "f0", "type": "textarea", "label": "A recent time I got angry"}, {"id": "f1", "type": "textarea", "label": "What mattered to me in that moment"}, {"id": "f2", "type": "textarea", "label": "What I did and what it cost"}, {"id": "f3", "type": "textarea", "label": "Another way to stand up for what matters"}]'::jsonb, array['anger management', 'core ACT', 'values']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('cooling-down-with-tipp-practice', 'Cooling Down With TIPP Practice', 'dbt'::resource_kind, 'A practice of tempering intense arousal with the TIPP skills, tried in session and planned for home.', 'Use it to help a client bring their body down before they decide what to do.', array['Adults', 'Teens']::text[], '30 minutes', 'Try temperature, intense exercise, paced breathing and paired relaxation in session as appropriate to the client''s health. Ask which works best. Remind them to check any health concerns before cold or exercise. Plan where to use it.', '[{"id": "f0", "type": "textarea", "label": "The skill I tried"}, {"id": "f1", "type": "textarea", "label": "What changed in my body"}, {"id": "f2", "type": "textarea", "label": "Which one worked best for me"}, {"id": "f3", "type": "textarea", "label": "Where I will use it this week"}]'::jsonb, array['anger management', 'core DBT', 'distress tolerance']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('volcano-feelings-spin-board', 'Volcano Feelings Spin Board', 'kids'::resource_kind, 'A craft where a child builds a spin board showing calm, rumbling and erupting, with a skill for each.', 'Use it to help a child match what their body feels with what helps.', array['Children']::text[], '35 minutes', 'The child builds a spin board with three zones and draws a body sign and a skill in each. Practice the skills together. The parent learns to model the same skills and to use the board when calm, not in the middle of an eruption.', '[{"id": "f0", "type": "textarea", "label": "What my calm looks like"}, {"id": "f1", "type": "textarea", "label": "What rumbling feels like"}, {"id": "f2", "type": "textarea", "label": "What I can do when I rumble"}, {"id": "f3", "type": "textarea", "label": "Who helps me at home"}]'::jsonb, array['anger management', 'children', 'regulation']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('intrusive-thought-naming-page', 'Intrusive Thought Naming Page', 'worksheet'::resource_kind, 'A page for labeling an intrusive thought as a thought and noting what the client did in response.', 'Use it to help a client step back from an unwanted thought and see the pattern that follows.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client write the thought in a neutral phrase and label it ''I am having the thought that.'' Then note what they did next, such as checking or reassurance seeking. Do not argue about content. Look at the cycle and where a small change might fit.', '[{"id": "f0", "type": "textarea", "label": "The intrusive thought, in neutral words"}, {"id": "f1", "type": "textarea", "label": "How anxious or uneasy it made me, zero to ten"}, {"id": "f2", "type": "textarea", "label": "What I did in response"}, {"id": "f3", "type": "textarea", "label": "What happened to the unease afterward"}, {"id": "f4", "type": "textarea", "label": "One small thing I could try differently"}]'::jsonb, array['OCD', 'thinking traps', 'self-monitoring']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('exposure-step-planner-with-response-delay', 'Exposure Step Planner With Response Delay', 'cbt'::resource_kind, 'A planner that sets an exposure step, a plan not to act on the urge and a tracker for how long they waited.', 'Use it to help a client practice facing a trigger while delaying a ritual.', array['Adults', 'Teens']::text[], '30 minutes', 'Choose a step the client rates as moderate and agree on how long to delay the ritual. Plan together what they will do while waiting. Record the urge rating at the start and end. Increase gradually and at the client''s pace.', '[{"id": "f0", "type": "textarea", "label": "The situation I will face"}, {"id": "f1", "type": "textarea", "label": "The urge I expect"}, {"id": "f2", "type": "textarea", "label": "How long I will delay"}, {"id": "f3", "type": "textarea", "label": "What I will do while I wait"}, {"id": "f4", "type": "textarea", "label": "How the urge changed"}]'::jsonb, array['OCD', 'core CBT', 'exposure', 'planning']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('doubt-passenger-practice', 'Doubt Passenger Practice', 'act'::resource_kind, 'A practice of letting doubt ride along while continuing with something that matters.', 'Use it to help a client carry doubt without letting it drive.', array['Adults', 'Teens']::text[], '20 minutes', 'Use the image of doubt as a passenger who gives loud directions. Have the client pick a task that matters and do it with doubt along. Ask what happened to their relationship with the doubt. Do not seek to remove the doubt.', '[{"id": "f0", "type": "textarea", "label": "What my doubt says"}, {"id": "f1", "type": "textarea", "label": "The task I chose"}, {"id": "f2", "type": "textarea", "label": "What I did while doubt was along"}, {"id": "f3", "type": "textarea", "label": "What mattered to me about doing it"}]'::jsonb, array['OCD', 'core ACT', 'defusion', 'uncertainty']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('wise-mind-about-checking-card', 'Wise Mind About Checking Card', 'dbt'::resource_kind, 'A card for pausing before a check and asking what wise mind says.', 'Use it to help a client pause and consider a response before doing a ritual.', array['Adults', 'Teens']::text[], '20 minutes', 'Practice the pause in session with a trigger of mild strength. The client writes down what emotion mind says and what wise mind says. Support them in choosing whether to act. Review how the urge changed.', '[{"id": "f0", "type": "textarea", "label": "What I felt like checking"}, {"id": "f1", "type": "textarea", "label": "What emotion mind told me"}, {"id": "f2", "type": "textarea", "label": "What wise mind said"}, {"id": "f3", "type": "textarea", "label": "What I chose to do"}]'::jsonb, array['OCD', 'core DBT', 'regulation']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('worry-bully-talk-back-poster', 'Worry Bully Talk-Back Poster', 'kids'::resource_kind, 'A poster activity where a child names the worry bully and writes brave talk-back lines.', 'Use it to help a child separate from the worry bully and answer it.', array['Children']::text[], '35 minutes', 'The child draws the worry bully and gives it a silly name. Together they write short talk-back lines. The parent learns not to give repeated reassurance and to say, ''That sounds like the bully.'' Practice the lines with a parent.', '[{"id": "f0", "type": "textarea", "label": "The name of my worry bully"}, {"id": "f1", "type": "textarea", "label": "What it says to me"}, {"id": "f2", "type": "textarea", "label": "What I can say back"}, {"id": "f3", "type": "textarea", "label": "What I can do instead of what it asks"}]'::jsonb, array['OCD', 'children', 'art', 'exposure']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('panic-sensation-prediction-chart', 'Panic Sensation Prediction Chart', 'worksheet'::resource_kind, 'A chart comparing what the client fears will happen in a panic wave with what happened.', 'Use it to help a client look at the gap between predictions and outcomes.', array['Adults', 'Teens']::text[], '20 minutes', 'Use a recent wave of panic and list the sensations. For each, note the feared meaning and what actually happened. Ask the client to review the chart after a few more waves. Encourage curiosity rather than argument.', '[{"id": "f0", "type": "textarea", "label": "The sensations I felt"}, {"id": "f1", "type": "textarea", "label": "What I feared they meant"}, {"id": "f2", "type": "textarea", "label": "What actually happened"}, {"id": "f3", "type": "textarea", "label": "How long it took to settle"}]'::jsonb, array['panic attacks', 'self-monitoring', 'anxiety']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('interoceptive-practice-log', 'Interoceptive Practice Log', 'cbt'::resource_kind, 'A log for brief, planned exercises that bring on harmless body sensations and the client''s response.', 'Use it to help a client get used to body sensations they fear, in small steps.', array['Adults']::text[], 'One week', 'Check the client''s health history first and consider a medical check. Try one exercise in session, such as breathing quickly for a short time, and rate the sensations. Assign only exercises practiced together. Increase slowly.', '[{"id": "f0", "type": "textarea", "label": "The exercise I did"}, {"id": "f1", "type": "textarea", "label": "Sensations I noticed"}, {"id": "f2", "type": "textarea", "label": "How much I feared them, zero to ten"}, {"id": "f3", "type": "textarea", "label": "What happened as I stayed with it"}]'::jsonb, array['panic attacks', 'core CBT', 'exposure']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('carrying-panic-through-the-day-practice', 'Carrying Panic Through the Day Practice', 'act'::resource_kind, 'A practice of taking panic along when doing something that matters instead of waiting for it to go.', 'Use it to help a client do what matters even with the possibility of panic.', array['Adults']::text[], '25 minutes', 'Ask what the client has stopped doing because of panic. Pick one small version and plan it with the panic allowed along. Rate what they learned afterward. Do not make the goal ''no panic.''', '[{"id": "f0", "type": "textarea", "label": "Something I stopped doing"}, {"id": "f1", "type": "textarea", "label": "The small version I will try"}, {"id": "f2", "type": "textarea", "label": "What I will say to my mind"}, {"id": "f3", "type": "textarea", "label": "What I noticed afterward"}]'::jsonb, array['panic attacks', 'core ACT', 'willingness']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('paced-breathing-and-temperature-reset', 'Paced Breathing and Temperature Reset', 'dbt'::resource_kind, 'A reset using slow exhale-focused breathing and cool water to settle body arousal.', 'Use it to help a client settle the body in a wave of panic.', array['Adults', 'Teens']::text[], '20 minutes', 'Try both skills in session and ask which one the client prefers. Advise on health considerations for cold water. Practice at calm times first so the skill is familiar. Review how it felt.', '[{"id": "f0", "type": "textarea", "label": "The skill I tried first"}, {"id": "f1", "type": "textarea", "label": "What changed in my body"}, {"id": "f2", "type": "textarea", "label": "Which one I prefer"}, {"id": "f3", "type": "textarea", "label": "When I will use it"}]'::jsonb, array['panic attacks', 'core DBT', 'distress tolerance']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('panic-plan-partners-can-follow', 'Panic Plan Partners Can Follow', 'couples'::resource_kind, 'A short plan for partners about what to say and do when panic arrives.', 'Use it to help partners support a panic wave in a calm, steady way.', array['Couples']::text[], '30 minutes', 'The person who has panic says what helps and what does not. The partner practices short, calm statements. Rehearse in session. Agree on a signal and a plan for afterward, including a check-in rather than a postmortem.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps in a wave"}, {"id": "f1", "type": "textarea", "label": "Partner A: what does not help"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I will say and do"}, {"id": "f3", "type": "textarea", "label": "The signal we will use"}, {"id": "f4", "type": "textarea", "label": "What we will do afterward"}]'::jsonb, array['panic attacks', 'support', 'couples']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('calm-reset-plan-for-parents', 'Calm Reset Plan for Parents', 'worksheet'::resource_kind, 'A plan for what a parent will do in the first minute of a hard moment with their child.', 'Use it to help a parent plan a pause before they respond.', array['Adults']::text[], '25 minutes', 'Name a real moment that happens often. The parent writes a pause, a phrase and a first action. Rehearse with a role play. Keep it short and realistic, and note repair is always possible later.', '[{"id": "f0", "type": "textarea", "label": "The moment that is hardest for me"}, {"id": "f1", "type": "textarea", "label": "What I notice in my body"}, {"id": "f2", "type": "textarea", "label": "The pause I will take"}, {"id": "f3", "type": "textarea", "label": "The words I will say"}, {"id": "f4", "type": "textarea", "label": "How I will repair if I need to"}]'::jsonb, array['parenting', 'regulation', 'planning']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('parent-thought-reframe-sheet', 'Parent Thought Reframe Sheet', 'cbt'::resource_kind, 'A sheet that turns harsh parent thoughts into balanced ones that support better responses.', 'Use it to help a parent notice thoughts that fuel reactive parenting.', array['Adults']::text[], '25 minutes', 'Collect thoughts like ''they are doing it on purpose.'' Explore other explanations such as tiredness or need. Be careful not to imply blame. Ask what response fits the balanced thought.', '[{"id": "f0", "type": "textarea", "label": "A thought I had about my child"}, {"id": "f1", "type": "textarea", "label": "How it made me feel"}, {"id": "f2", "type": "textarea", "label": "Another way to see it"}, {"id": "f3", "type": "textarea", "label": "What I could do with that view"}]'::jsonb, array['parenting', 'core CBT', 'automatic thoughts']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('parent-best-self-compass', 'Parent Best Self Compass', 'act'::resource_kind, 'A compass for choosing a parenting action based on who the parent wants to be.', 'Use it to help a parent act on values when emotions run high.', array['Adults']::text[], '25 minutes', 'Ask the parent to name three qualities they want their child to remember. Connect each to a small action. Name the hooks that pull them away. Review how it felt to act on a value.', '[{"id": "f0", "type": "textarea", "label": "Qualities I want my child to remember"}, {"id": "f1", "type": "textarea", "label": "A small action for each"}, {"id": "f2", "type": "textarea", "label": "What pulls me away"}, {"id": "f3", "type": "textarea", "label": "What I will do when I notice it"}]'::jsonb, array['parenting', 'core ACT', 'values']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('validating-my-child-practice-page', 'Validating My Child Practice Page', 'dbt'::resource_kind, 'A page for practicing validating a child''s feeling before problem solving.', 'Use it to help a parent show understanding of a child''s feelings first.', array['Adults']::text[], '25 minutes', 'Review levels of validation with simple examples. Practice with a role play where the clinician plays the child. Watch for ''but'' after validation. Assign one validating moment a day.', '[{"id": "f0", "type": "textarea", "label": "A feeling my child had"}, {"id": "f1", "type": "textarea", "label": "A validating sentence I could say"}, {"id": "f2", "type": "textarea", "label": "What I did instead"}, {"id": "f3", "type": "textarea", "label": "What I will try next time"}]'::jsonb, array['parenting', 'core DBT', 'validation']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('family-feelings-pointer-wheel', 'Family Feelings Pointer Wheel', 'kids'::resource_kind, 'A craft where the family builds a wheel to point at how each person feels at the day''s start.', 'Use it to help families notice and share feelings in a simple way.', array['Children', 'Adults']::text[], '30 minutes', 'The child decorates the wheel and chooses the feeling choices with the parent. Use it daily for two weeks. The parent models by pointing first and responding with curiosity. Keep the wheel on the fridge or door.', '[{"id": "f0", "type": "textarea", "label": "The feelings I chose for the wheel"}, {"id": "f1", "type": "textarea", "label": "How I like others to respond"}, {"id": "f2", "type": "textarea", "label": "Where we will keep it"}, {"id": "f3", "type": "textarea", "label": "When we will use it"}]'::jsonb, array['parenting', 'children', 'family']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('rest-and-help-request-planner', 'Rest and Help Request Planner', 'worksheet'::resource_kind, 'A planner for deciding when to rest and what help to ask from whom in the first weeks with a baby.', 'Use it to help a new parent plan rest and ask for specific help.', array['Adults']::text[], '20 minutes', 'Ask for concrete help, like a two-hour nap block. List possible helpers and a request for each. Role-play asking. Include in the note a reminder for clients to tell their care team if they feel unsafe. Share 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "When I most need rest"}, {"id": "f1", "type": "textarea", "label": "Who could help and with what"}, {"id": "f2", "type": "textarea", "label": "The words I will use to ask"}, {"id": "f3", "type": "textarea", "label": "If I feel unsafe or overwhelmed, who I will call, including 988 (call or text)"}]'::jsonb, array['perinatal and postpartum', 'support', 'planning']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('new-parent-harsh-thought-record', 'New Parent Harsh Thought Record', 'cbt'::resource_kind, 'A thought record for harsh thoughts about being a new parent.', 'Use it to help a new parent notice and soften harsh thoughts about themselves.', array['Adults']::text[], '25 minutes', 'Collect thoughts like ''I should know what to do.'' Look for the evidence and a gentler view. Note sleep loss. Keep the tone warm and avoid labeling anything as a condition.', '[{"id": "f0", "type": "textarea", "label": "The thought I had"}, {"id": "f1", "type": "textarea", "label": "What I felt"}, {"id": "f2", "type": "textarea", "label": "What I would say to a friend"}, {"id": "f3", "type": "textarea", "label": "A kinder thought"}]'::jsonb, array['perinatal and postpartum', 'core CBT', 'self-criticism']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('values-in-the-early-weeks-page', 'Values in the Early Weeks Page', 'act'::resource_kind, 'A page for choosing small actions that fit what matters in the early weeks of parenting.', 'Use it to help a new parent act on values within a limited day.', array['Adults']::text[], '20 minutes', 'Name two values the parent wants to keep. Then choose very small actions, such as a minute of eye contact. Accept the day as it is. Ask what noticing these moments does.', '[{"id": "f0", "type": "textarea", "label": "Two things that matter to me"}, {"id": "f1", "type": "textarea", "label": "A tiny action for each"}, {"id": "f2", "type": "textarea", "label": "What gets in the way"}, {"id": "f3", "type": "textarea", "label": "What I will do when it does"}]'::jsonb, array['perinatal and postpartum', 'core ACT', 'values']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('self-soothe-for-night-feeds-kit', 'Self-Soothe for Night Feeds Kit', 'dbt'::resource_kind, 'A kit list of gentle sensory comforts for night feeds and long nights.', 'Use it to help a new parent prepare calming steps for hard nights.', array['Adults']::text[], '20 minutes', 'Build a small kit of safe, simple items together. Think of dim light, a warm drink or a soft song. Practice using it once in the room. Remind the client to make a plan with their partner for rest.', '[{"id": "f0", "type": "textarea", "label": "What I can see or hear"}, {"id": "f1", "type": "textarea", "label": "What I can smell or taste"}, {"id": "f2", "type": "textarea", "label": "What I can feel in my hands"}, {"id": "f3", "type": "textarea", "label": "Who can take over so I can rest"}]'::jsonb, array['perinatal and postpartum', 'self-soothing', 'distress tolerance']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('night-shift-teamwork-agreement', 'Night Shift Teamwork Agreement', 'couples'::resource_kind, 'An agreement on how partners share nights, chores and check-ins in the first months.', 'Use it to help partners share the load and stay connected.', array['Couples']::text[], '35 minutes', 'Each partner lists what they are carrying. Then they draft shifts and a weekly check-in. Look for fairness, not equality of hours. Revisit the plan every week since needs change.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I am carrying"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I am carrying"}, {"id": "f2", "type": "textarea", "label": "Our shifts for the week"}, {"id": "f3", "type": "textarea", "label": "How we will check in"}]'::jsonb, array['perinatal and postpartum', 'relationship issues', 'planning']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('qualities-i-like-in-me-inventory', 'Qualities I Like in Me Inventory', 'worksheet'::resource_kind, 'An inventory of qualities the client sees in themselves and moments that show them.', 'Use it to help a client build a grounded list of strengths with examples.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask for a quality and a recent moment that shows it. If the client struggles, invite what a friend would say. Keep notes in the client''s words. Revisit the list weekly and add to it.', '[{"id": "f0", "type": "textarea", "label": "A quality I like in myself"}, {"id": "f1", "type": "textarea", "label": "A moment that shows it"}, {"id": "f2", "type": "textarea", "label": "What a friend would say about me"}, {"id": "f3", "type": "textarea", "label": "One I want to grow"}]'::jsonb, array['self-esteem', 'strengths']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('self-criticism-evidence-review', 'Self-Criticism Evidence Review', 'cbt'::resource_kind, 'A review of a harsh self-judgment with evidence for and against it.', 'Use it to help a client look at the facts behind a harsh self-judgment.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose a recurring self-criticism. Fill in evidence on both sides and ask for a fairer summary. Notice how the client talks to themselves, and practice a different voice. Do not push an overly positive claim.', '[{"id": "f0", "type": "textarea", "label": "The criticism I say to myself"}, {"id": "f1", "type": "textarea", "label": "Evidence that supports it"}, {"id": "f2", "type": "textarea", "label": "Evidence that does not"}, {"id": "f3", "type": "textarea", "label": "A fairer sentence"}]'::jsonb, array['self-esteem', 'core CBT', 'self-criticism']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('self-as-context-observer-notes', 'Self as Context Observer Notes', 'act'::resource_kind, 'Notes from watching the self that notices, rather than the self described by thoughts.', 'Use it to help a client see themselves as more than a set of stories.', array['Adults', 'Teens']::text[], '25 minutes', 'Guide a short exercise of noticing thoughts, body and feelings from an observer view. Then ask the client what stays the same. Keep it practical. Ask how the observer view changes their relationship to a harsh story.', '[{"id": "f0", "type": "textarea", "label": "A story I tell about myself"}, {"id": "f1", "type": "textarea", "label": "What I notice when I watch it"}, {"id": "f2", "type": "textarea", "label": "What stays the same in me"}, {"id": "f3", "type": "textarea", "label": "What I choose to do next"}]'::jsonb, array['self-esteem', 'core ACT', 'self-compassion']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('validate-myself-daily-cards', 'Validate Myself Daily Cards', 'dbt'::resource_kind, 'Cards with self-validating sentences the client can say about feelings and effort.', 'Use it to help a client acknowledge their own feelings without judgment.', array['Adults', 'Teens']::text[], '20 minutes', 'Write a few validating sentences with the client, such as ''It makes sense I feel this way.'' Practice aloud. Ask how it feels. Assign one daily use.', '[{"id": "f0", "type": "textarea", "label": "A feeling I had today"}, {"id": "f1", "type": "textarea", "label": "A sentence that validates it"}, {"id": "f2", "type": "textarea", "label": "How it felt to say it"}, {"id": "f3", "type": "textarea", "label": "When I will use these cards"}]'::jsonb, array['self-esteem', 'core DBT', 'validation']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('compliment-circle-with-a-twist', 'Compliment Circle With a Twist', 'game'::resource_kind, 'A group game of giving and receiving specific, non-appearance compliments.', 'Use it to help players practice giving and receiving specific recognition.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Players take turns giving a specific compliment about a quality or action. The receiver says thank you and nothing more. Rule out comments on appearance. In the debrief, ask what was hard about receiving.', '[{"id": "f0", "type": "textarea", "label": "A compliment I gave"}, {"id": "f1", "type": "textarea", "label": "One I received"}, {"id": "f2", "type": "textarea", "label": "What was hard to accept"}, {"id": "f3", "type": "textarea", "label": "What I want to remember"}]'::jsonb, array['self-esteem', 'group', 'play']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('social-spotlight-reality-check', 'Social Spotlight Reality Check', 'worksheet'::resource_kind, 'A page comparing how much the client thinks others noticed with what they actually saw.', 'Use it to help a client check the spotlight effect on their own events.', array['Adults', 'Teens']::text[], '20 minutes', 'Pick a recent event. Compare the client''s beliefs with what a friend might have noticed. If possible, have them ask a trusted person. Be gentle about conclusions.', '[{"id": "f0", "type": "textarea", "label": "The event"}, {"id": "f1", "type": "textarea", "label": "What I think they noticed"}, {"id": "f2", "type": "textarea", "label": "What a friend says they noticed"}, {"id": "f3", "type": "textarea", "label": "What I take from this"}]'::jsonb, array['social anxiety', 'core CBT', 'thinking traps']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('attention-shift-conversation-test', 'Attention Shift Conversation Test', 'cbt'::resource_kind, 'An experiment comparing a conversation with attention on self against attention on the other person.', 'Use it to help a client test what happens when attention moves outward.', array['Adults', 'Teens']::text[], '25 minutes', 'Plan two short conversations. In one, focus on self-monitoring. In the other, focus on listening. Compare anxiety and experience. Discuss what the contrast suggests.', '[{"id": "f0", "type": "textarea", "label": "How I felt with attention on myself"}, {"id": "f1", "type": "textarea", "label": "How I felt with attention on them"}, {"id": "f2", "type": "textarea", "label": "What I noticed about the conversation"}, {"id": "f3", "type": "textarea", "label": "What I will try again"}]'::jsonb, array['social anxiety', 'core CBT', 'behavioral experiment']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('social-moments-values-page', 'Social Moments Values Page', 'act'::resource_kind, 'A page connecting a social situation with a value and a willing step.', 'Use it to help a client go toward people while anxious.', array['Adults', 'Teens']::text[], '25 minutes', 'Pick a value, such as friendliness or curiosity. Plan a social action that fits and a way to carry the anxiety along. Keep the steps small. Ask what mattered about the action.', '[{"id": "f0", "type": "textarea", "label": "The value I want to act on"}, {"id": "f1", "type": "textarea", "label": "A social step that fits"}, {"id": "f2", "type": "textarea", "label": "What my mind will say"}, {"id": "f3", "type": "textarea", "label": "What I will do with that"}]'::jsonb, array['social anxiety', 'core ACT', 'values']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('give-skill-rehearsal-cards', 'GIVE Skill Rehearsal Cards', 'dbt'::resource_kind, 'Cards to rehearse the GIVE skills in a short conversation.', 'Use it to help a client practice warm, relationship-minded conversation.', array['Adults', 'Teens']::text[], '25 minutes', 'Walk through gentle, interested, validate and easy manner. Practice each with a clinician role play. Use a low-stakes topic. Give feedback on what went well first.', '[{"id": "f0", "type": "textarea", "label": "The conversation I practiced"}, {"id": "f1", "type": "textarea", "label": "The part of GIVE that came easiest"}, {"id": "f2", "type": "textarea", "label": "The part that was harder"}, {"id": "f3", "type": "textarea", "label": "What I will try this week"}]'::jsonb, array['social anxiety', 'core DBT', 'interpersonal effectiveness']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('small-talk-spin-game', 'Small Talk Spin Game', 'game'::resource_kind, 'A group game using spinner topics to practice starting and ending short conversations.', 'Use it to help players practice small talk in a safe setting.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Make a spinner of casual topics. Players pair up and talk for one minute and then swap. Keep it light and let anyone pass. In the debrief, name what was easier than expected.', '[{"id": "f0", "type": "textarea", "label": "Topic I spun"}, {"id": "f1", "type": "textarea", "label": "What I said"}, {"id": "f2", "type": "textarea", "label": "What was easier than expected"}, {"id": "f3", "type": "textarea", "label": "What I want to try outside"}]'::jsonb, array['social anxiety', 'group', 'play']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('grief-anniversary-plan', 'Grief Anniversary Plan', 'worksheet'::resource_kind, 'A plan for a hard date: what the client wants to do, who they want near and how they will care for themselves.', 'Use it to help a client prepare for a date that carries extra weight.', array['Adults', 'Teens']::text[], '25 minutes', 'Plan ahead for birthdays, holidays or anniversaries. Let the client choose between marking the day, keeping it quiet or a mix. Name one person to contact. Check in after the date to see what helped.', '[{"id": "f0", "type": "textarea", "label": "The date and what it means"}, {"id": "f1", "type": "textarea", "label": "How I want to spend it"}, {"id": "f2", "type": "textarea", "label": "Who I want near me"}, {"id": "f3", "type": "textarea", "label": "How I will care for myself afterward"}]'::jsonb, array['grief and loss', 'planning', 'support']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('grief-thought-check-for-self-blame', 'Grief Thought Check for Self-Blame', 'cbt'::resource_kind, 'A check of self-blame thoughts about the loss, with kinder and fairer views.', 'Use it to help a client look at guilt-heavy thoughts with more balance.', array['Adults']::text[], '25 minutes', 'Collect thoughts like ''I should have known.'' Explore what the client knew at the time and what hindsight adds. Do not argue away their sorrow. Offer a view that includes both love and limits.', '[{"id": "f0", "type": "textarea", "label": "The thought I keep having"}, {"id": "f1", "type": "textarea", "label": "What I knew at the time"}, {"id": "f2", "type": "textarea", "label": "What I know now that I could not know then"}, {"id": "f3", "type": "textarea", "label": "A fairer sentence"}]'::jsonb, array['grief and loss', 'core CBT', 'self-criticism']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('honoring-their-memory-through-action', 'Honoring Their Memory Through Action', 'act'::resource_kind, 'A practice of keeping a bond with someone lost by choosing actions that honor them.', 'Use it to help a client let grief and love sit side by side.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what the client loved about the person and what they valued together. Then plan one small act that carries it. Let pain be present. Return to how the act felt next time.', '[{"id": "f0", "type": "textarea", "label": "What I loved about them"}, {"id": "f1", "type": "textarea", "label": "What we valued together"}, {"id": "f2", "type": "textarea", "label": "A small act that carries it forward"}, {"id": "f3", "type": "textarea", "label": "How it felt"}]'::jsonb, array['grief and loss', 'core ACT', 'values', 'connection']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('getting-through-a-grief-wave-card', 'Getting Through a Grief Wave Card', 'dbt'::resource_kind, 'A card with skills for getting through a wave of grief without making it worse.', 'Use it to help a client get through a hard wave of grief.', array['Adults', 'Teens']::text[], '20 minutes', 'Build a card with a few skills from the distress tolerance set that suit grief. Include one comfort and one connection. Try it in session. Mention that waves are expected.', '[{"id": "f0", "type": "textarea", "label": "Skills that help during a wave"}, {"id": "f1", "type": "textarea", "label": "One comfort I can reach"}, {"id": "f2", "type": "textarea", "label": "One person I can reach"}, {"id": "f3", "type": "textarea", "label": "How I will know the wave is passing"}]'::jsonb, array['grief and loss', 'core DBT', 'distress tolerance']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('memory-garden-drawing-book', 'Memory Garden Drawing Book', 'kids'::resource_kind, 'A drawing book where a child draws memories of someone they miss as flowers.', 'Use it to give a child a gentle way to remember and talk about a loss.', array['Children']::text[], '40 minutes', 'The child draws a flower for each memory and tells a bit about it. Let them lead and stop when they want. The parent learns to listen without fixing and to expect feelings to come and go in waves. Answer questions about death honestly and simply.', '[{"id": "f0", "type": "textarea", "label": "A memory I drew"}, {"id": "f1", "type": "textarea", "label": "How I feel about it"}, {"id": "f2", "type": "textarea", "label": "What I miss most"}, {"id": "f3", "type": "textarea", "label": "Who I can talk to about it"}]'::jsonb, array['grief and loss', 'children', 'art']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('needs-and-requests-translator', 'Needs and Requests Translator', 'worksheet'::resource_kind, 'A sheet that turns a complaint into a need and a clear request.', 'Use it to help a client turn criticism into a request their partner can act on.', array['Adults']::text[], '20 minutes', 'Start with a real complaint and ask what need sits under it. Then write a request that is specific and doable. Role-play saying it. Avoid blame words.', '[{"id": "f0", "type": "textarea", "label": "The complaint I have"}, {"id": "f1", "type": "textarea", "label": "The need underneath"}, {"id": "f2", "type": "textarea", "label": "My request in one sentence"}, {"id": "f3", "type": "textarea", "label": "How I will say it kindly"}]'::jsonb, array['relationship issues', 'communication', 'assertiveness']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('relationship-mind-reading-check', 'Relationship Mind Reading Check', 'cbt'::resource_kind, 'A check of assumptions about a partner''s thoughts, with ways to test them.', 'Use it to help a client check assumptions before reacting.', array['Adults']::text[], '25 minutes', 'List assumptions that show up in conflict and mark how sure the client feels. Think of other explanations and a way to ask. Practice the asking line aloud.', '[{"id": "f0", "type": "textarea", "label": "The assumption I made"}, {"id": "f1", "type": "textarea", "label": "How sure I felt"}, {"id": "f2", "type": "textarea", "label": "Other explanations"}, {"id": "f3", "type": "textarea", "label": "A question I could ask"}]'::jsonb, array['relationship issues', 'core CBT', 'thinking traps']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('partner-i-want-to-be-compass', 'Partner I Want to Be Compass', 'act'::resource_kind, 'A compass for choosing actions that match the kind of partner the client wants to be.', 'Use it to help a client act on values in a tense moment.', array['Adults']::text[], '25 minutes', 'Ask about the partner they want to be on their best day. Then choose small actions. Identify the hooks that tempt them to defend or withdraw. Practice a response.', '[{"id": "f0", "type": "textarea", "label": "The partner I want to be"}, {"id": "f1", "type": "textarea", "label": "A small action that fits"}, {"id": "f2", "type": "textarea", "label": "What hooks me"}, {"id": "f3", "type": "textarea", "label": "What I do when I notice it"}]'::jsonb, array['relationship issues', 'core ACT', 'values']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('dear-man-for-hard-requests-rehearsal', 'DEAR MAN for Hard Requests Rehearsal', 'dbt'::resource_kind, 'A script sheet for rehearsing a request with DEAR MAN.', 'Use it to help a client prepare a clear and respectful request.', array['Adults']::text[], '30 minutes', 'Go through each letter and write the client''s own words. Role-play with the clinician. Coach on staying with the point and on a calm tone. Review after use.', '[{"id": "f0", "type": "textarea", "label": "The situation I describe"}, {"id": "f1", "type": "textarea", "label": "How I express my feelings"}, {"id": "f2", "type": "textarea", "label": "What I ask for"}, {"id": "f3", "type": "textarea", "label": "What I offer in return"}]'::jsonb, array['relationship issues', 'core DBT', 'interpersonal effectiveness']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('weekly-relationship-check-in-guide', 'Weekly Relationship Check-In Guide', 'couples'::resource_kind, 'A guide for a weekly talk that covers appreciation, concerns and plans.', 'Use it to help partners keep up with each other before small things build up.', array['Couples']::text[], '45 minutes', 'Set a regular time and keep it to about forty-five minutes. Start with appreciation, then take turns on concerns, then plan. The listener summarizes before responding. Stop if either partner is flooded.', '[{"id": "f0", "type": "textarea", "label": "Partner A: something I appreciate"}, {"id": "f1", "type": "textarea", "label": "Partner B: something I appreciate"}, {"id": "f2", "type": "textarea", "label": "A concern from each of us"}, {"id": "f3", "type": "textarea", "label": "Our plan for the week"}]'::jsonb, array['relationship issues', 'communication', 'couples']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('safety-and-support-circle-map', 'Safety and Support Circle Map', 'worksheet'::resource_kind, 'A map of the people, places and routines that help a client feel safe now.', 'Use it to help a client identify present-day sources of safety and support.', array['Adults']::text[], '25 minutes', 'This tool is about the present. Do not ask for details of what happened. Have the client name people, places and routines that feel safe, and mark where more support is needed. Remind them about 988 (call or text) and other supports for hard moments.', '[{"id": "f0", "type": "textarea", "label": "People who help me feel safe"}, {"id": "f1", "type": "textarea", "label": "Places that feel safe"}, {"id": "f2", "type": "textarea", "label": "Routines that steady me"}, {"id": "f3", "type": "textarea", "label": "Who I can contact if I feel unsafe, including 988 (call or text)"}]'::jsonb, array['sexual abuse', 'safety', 'support']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('self-blame-thought-pacing-sheet', 'Self-Blame Thought Pacing Sheet', 'cbt'::resource_kind, 'A sheet for looking at self-blame thoughts at a pace the client controls, without retelling events.', 'Use it to help a client notice self-blame and consider a fairer view in the present.', array['Adults']::text[], '25 minutes', 'Keep to thoughts, not events. The client names a thought and a fairer thought that places responsibility where it belongs. Pause if they feel flooded and ground. Stay in session with this one rather than homework.', '[{"id": "f0", "type": "textarea", "label": "A thought I have about myself"}, {"id": "f1", "type": "textarea", "label": "How strongly I believe it, zero to ten"}, {"id": "f2", "type": "textarea", "label": "A fairer thought"}, {"id": "f3", "type": "textarea", "label": "What helps me feel grounded now"}]'::jsonb, array['sexual abuse', 'core CBT', 'pacing']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('present-moment-anchors-and-values-page', 'Present Moment Anchors and Values Page', 'act'::resource_kind, 'A page that pairs anchors for the present with values the client wants to move toward.', 'Use it to help a client feel anchored in the present and take small steps toward what matters.', array['Adults']::text[], '20 minutes', 'Start with anchors such as feet on the floor and sounds in the room. Then name a value and a small action. Keep the pace slow and the client in charge. Include a way to stop.', '[{"id": "f0", "type": "textarea", "label": "Anchors that help me feel here"}, {"id": "f1", "type": "textarea", "label": "A value I care about"}, {"id": "f2", "type": "textarea", "label": "A small step toward it"}, {"id": "f3", "type": "textarea", "label": "How I will pause if I need to"}]'::jsonb, array['sexual abuse', 'core ACT', 'grounding']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('boundaries-and-safe-choices-practice', 'Boundaries and Safe Choices Practice', 'dbt'::resource_kind, 'A practice of stating a boundary and choosing safe, supportive options in current relationships.', 'Use it to help a client practice boundaries in relationships today.', array['Adults', 'Teens']::text[], '30 minutes', 'Work on current boundaries and choices, not past events. Practice a short sentence and a plan if it is not respected. Role-play with clinician. Make sure the client knows they decide the pace.', '[{"id": "f0", "type": "textarea", "label": "A boundary I want in a current relationship"}, {"id": "f1", "type": "textarea", "label": "My sentence"}, {"id": "f2", "type": "textarea", "label": "What I will do if it is not respected"}, {"id": "f3", "type": "textarea", "label": "Who supports me"}]'::jsonb, array['sexual abuse', 'core DBT', 'boundaries', 'interpersonal effectiveness']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('my-body-is-my-own-rules-poster', 'My Body Is My Own Rules Poster', 'kids'::resource_kind, 'A poster activity about body safety rules, safe adults and telling someone.', 'Use it to help a child learn body safety rules and who to tell.', array['Children']::text[], '35 minutes', 'The child decorates a poster with simple rules and draws safe adults on a hand. Use plain, age-appropriate words and no details of harm. The parent learns to respond calmly if their child tells them something. If a child discloses abuse, follow your mandated reporting duties and local rules.', '[{"id": "f0", "type": "textarea", "label": "A rule about my body that I know"}, {"id": "f1", "type": "textarea", "label": "Safe adults I can tell"}, {"id": "f2", "type": "textarea", "label": "What I can say if something feels wrong"}, {"id": "f3", "type": "textarea", "label": "Where I will hang my poster"}]'::jsonb, array['sexual abuse', 'children', 'safety', 'art']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('coping-menu-by-time-and-place', 'Coping Menu by Time and Place', 'worksheet'::resource_kind, 'A menu sorting coping skills by where the client is and how much time they have.', 'Use it to help a client pick a skill that fits the moment.', array['Adults', 'Teens']::text[], '25 minutes', 'Make a grid of places (home, work, public) and times (one minute, ten minutes, an hour). Fill in skills for each cell. Test one in session. Keep a copy on a phone.', '[{"id": "f0", "type": "textarea", "label": "Skills for one minute"}, {"id": "f1", "type": "textarea", "label": "Skills for ten minutes"}, {"id": "f2", "type": "textarea", "label": "Skills that work in public"}, {"id": "f3", "type": "textarea", "label": "Skills I want to learn"}]'::jsonb, array['coping skills', 'planning', 'skills']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('coping-ahead-rehearsal-sheet', 'Coping Ahead Rehearsal Sheet', 'cbt'::resource_kind, 'A sheet that prepares for a hard event with thoughts, steps and coping plans.', 'Use it to help a client rehearse coping before a hard event.', array['Adults', 'Teens']::text[], '30 minutes', 'Choose an upcoming event. Walk through what could go wrong and what the client could do. Rehearse in imagination or role play. Review after the event.', '[{"id": "f0", "type": "textarea", "label": "The event"}, {"id": "f1", "type": "textarea", "label": "What could be hard"}, {"id": "f2", "type": "textarea", "label": "What I can do"}, {"id": "f3", "type": "textarea", "label": "What I will tell myself"}]'::jsonb, array['coping skills', 'core CBT', 'planning']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('does-my-coping-move-me-toward-what-matters', 'Does My Coping Move Me Toward What Matters', 'act'::resource_kind, 'A check of whether each coping habit helps in the short term and the long term.', 'Use it to help a client sort habits by whether they move them toward what matters.', array['Adults', 'Teens']::text[], '25 minutes', 'List coping habits and ask whether each works toward a valued life. No habit is shamed. Mark which to keep, adjust or add to. Return to the list after a week.', '[{"id": "f0", "type": "textarea", "label": "A coping habit I use"}, {"id": "f1", "type": "textarea", "label": "What it gives me now"}, {"id": "f2", "type": "textarea", "label": "What it costs me later"}, {"id": "f3", "type": "textarea", "label": "Keep, change or add to it"}]'::jsonb, array['coping skills', 'core ACT', 'workability']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('tipp-and-self-soothe-mix-card', 'TIPP and Self-Soothe Mix Card', 'dbt'::resource_kind, 'A pocket card combining a body-based skill and a soothing skill.', 'Use it to help a client have quick skills ready for hard moments.', array['Adults', 'Teens']::text[], '20 minutes', 'Choose one TIPP element and one soothing sense. Write both on a card. Try them in session. Remind about health considerations for cold or exercise.', '[{"id": "f0", "type": "textarea", "label": "The body skill I chose"}, {"id": "f1", "type": "textarea", "label": "The soothing skill I chose"}, {"id": "f2", "type": "textarea", "label": "When I will use them"}, {"id": "f3", "type": "textarea", "label": "How I felt after trying them"}]'::jsonb, array['coping skills', 'core DBT', 'distress tolerance']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('coping-skills-acting-relay', 'Coping Skills Acting Relay', 'game'::resource_kind, 'A relay where teams act out coping skills for others to guess and then discuss.', 'Use it to help players recall and share coping skills in a fun way.', array['Children', 'Teens', 'Groups']::text[], '30 minutes', 'Make cards with skills. Teams act them out for guesses. After each round, ask when the skill might help. Close by asking each player to choose one to try.', '[{"id": "f0", "type": "textarea", "label": "A skill I acted out or guessed"}, {"id": "f1", "type": "textarea", "label": "When it could help"}, {"id": "f2", "type": "textarea", "label": "One I want to try"}, {"id": "f3", "type": "textarea", "label": "Who can remind me"}]'::jsonb, array['coping skills', 'group', 'play']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('fear-ladder-with-support-notes', 'Fear Ladder With Support Notes', 'worksheet'::resource_kind, 'A ladder of feared situations from easiest to hardest, with notes on support for each rung.', 'Use it to help a client plan graded steps toward a feared situation.', array['Adults', 'Teens']::text[], '30 minutes', 'Build the ladder with the client and rate each rung. Add support such as a person or a skill. Start with a rung they rate as moderate. Revisit and reorder as needed.', '[{"id": "f0", "type": "textarea", "label": "The feared situation"}, {"id": "f1", "type": "textarea", "label": "Steps from easiest to hardest"}, {"id": "f2", "type": "textarea", "label": "Difficulty of each, zero to ten"}, {"id": "f3", "type": "textarea", "label": "Support for the first step"}]'::jsonb, array['phobias', 'exposure', 'planning']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('fear-prediction-and-outcome-table', 'Fear Prediction and Outcome Table', 'cbt'::resource_kind, 'A table to record what the client predicts and what happened in a feared situation.', 'Use it to help a client compare predictions with what happened.', array['Adults', 'Teens']::text[], '20 minutes', 'Fill the first two columns before each exposure and the last two afterward. Compare and look for differences. Do not rush to a conclusion. Plan the next step.', '[{"id": "f0", "type": "textarea", "label": "What I predict will happen"}, {"id": "f1", "type": "textarea", "label": "How afraid I expect to be"}, {"id": "f2", "type": "textarea", "label": "What happened"}, {"id": "f3", "type": "textarea", "label": "What I learned"}]'::jsonb, array['phobias', 'core CBT', 'exposure', 'behavioral experiment']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('fear-along-for-the-ride-practice', 'Fear Along for the Ride Practice', 'act'::resource_kind, 'A practice of taking a step toward a feared situation with fear present and a value in mind.', 'Use it to help a client do a valued thing while afraid.', array['Adults', 'Teens']::text[], '25 minutes', 'Name what the fear stops them from doing and why that matters. Pick a step and rate willingness. Practice with the fear along. Ask what they noticed.', '[{"id": "f0", "type": "textarea", "label": "What my fear stops me from doing"}, {"id": "f1", "type": "textarea", "label": "Why that matters to me"}, {"id": "f2", "type": "textarea", "label": "The step I will take"}, {"id": "f3", "type": "textarea", "label": "What I noticed"}]'::jsonb, array['phobias', 'core ACT', 'values', 'willingness']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('opposite-action-approach-plan', 'Opposite Action Approach Plan', 'dbt'::resource_kind, 'A plan for approaching a feared situation when the fear is not matching the facts.', 'Use it to help a client approach rather than avoid when facts support it.', array['Adults', 'Teens']::text[], '25 minutes', 'Check the facts first. If the situation is safe, plan an approach step with full commitment in posture and words. Practice in session. Review how it went.', '[{"id": "f0", "type": "textarea", "label": "The fear and the facts"}, {"id": "f1", "type": "textarea", "label": "My approach step"}, {"id": "f2", "type": "textarea", "label": "How I will do it fully"}, {"id": "f3", "type": "textarea", "label": "What happened"}]'::jsonb, array['phobias', 'core DBT', 'opposite action', 'avoidance']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('brave-steps-sticker-board', 'Brave Steps Sticker Board', 'kids'::resource_kind, 'A board with steps toward a feared thing, with a sticker for each step tried.', 'Use it to help a child approach a fear in small steps with a parent cheering.', array['Children']::text[], '30 minutes', 'The child draws the feared thing small and then picks steps on a board. A sticker goes on for each try, whatever the outcome. The parent practices encouraging without pushing and avoids rescuing at the first sign of worry.', '[{"id": "f0", "type": "textarea", "label": "My fear in a small drawing"}, {"id": "f1", "type": "textarea", "label": "My first brave step"}, {"id": "f2", "type": "textarea", "label": "My second brave step"}, {"id": "f3", "type": "textarea", "label": "Who will cheer me on"}]'::jsonb, array['phobias', 'children', 'exposure', 'play']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('body-appreciation-function-list', 'Body Appreciation Function List', 'worksheet'::resource_kind, 'A list of things the client''s body lets them do, feel and share.', 'Use it to help a client notice what their body does for them.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask for functions and experiences, such as hugging a friend or walking in the park. Add sensory moments. Avoid any appearance talk. Review the list and add items weekly.', '[{"id": "f0", "type": "textarea", "label": "Things my body lets me do"}, {"id": "f1", "type": "textarea", "label": "Moments I enjoyed with my body"}, {"id": "f2", "type": "textarea", "label": "Something I am grateful for"}, {"id": "f3", "type": "textarea", "label": "One more to add this week"}]'::jsonb, array['body image', 'self-compassion', 'strengths']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('appearance-thought-pause-log', 'Appearance Thought Pause Log', 'cbt'::resource_kind, 'A log of thoughts about appearance, what triggered them and a kinder way to respond.', 'Use it to help a client notice appearance thoughts and respond with flexibility.', array['Adults', 'Teens']::text[], '25 minutes', 'Collect triggers such as mirrors or social media. Ask for the thought and its effect on the day. Explore other things to attend to. Keep the focus on thoughts and actions.', '[{"id": "f0", "type": "textarea", "label": "What set off the thought"}, {"id": "f1", "type": "textarea", "label": "The thought"}, {"id": "f2", "type": "textarea", "label": "What I did next"}, {"id": "f3", "type": "textarea", "label": "A kinder response"}]'::jsonb, array['body image', 'core CBT', 'self-talk']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('values-beyond-appearance-page', 'Values Beyond Appearance Page', 'act'::resource_kind, 'A page for choosing actions guided by values instead of by looks.', 'Use it to help a client move toward what matters, whatever thoughts about appearance say.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what the client would do more of if appearance thoughts were quieter. Choose a small action. Name the hooks. Revisit after practice.', '[{"id": "f0", "type": "textarea", "label": "What I would do if the thoughts were quieter"}, {"id": "f1", "type": "textarea", "label": "A small step toward it"}, {"id": "f2", "type": "textarea", "label": "What my mind says"}, {"id": "f3", "type": "textarea", "label": "What I do with that"}]'::jsonb, array['body image', 'core ACT', 'values']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('self-validation-and-kindness-cards', 'Self-Validation and Kindness Cards', 'dbt'::resource_kind, 'Cards with validating and kind statements for hard moments about how one looks.', 'Use it to help a client respond to a hard moment with validation.', array['Adults', 'Teens']::text[], '20 minutes', 'Write statements together, such as ''It is hard to feel this way and I can be kind to myself.'' Practice aloud. Choose one for the mirror or phone. Revisit and refine.', '[{"id": "f0", "type": "textarea", "label": "A hard moment"}, {"id": "f1", "type": "textarea", "label": "A validating sentence"}, {"id": "f2", "type": "textarea", "label": "A kind action I can take"}, {"id": "f3", "type": "textarea", "label": "Where I will keep these cards"}]'::jsonb, array['body image', 'core DBT', 'validation', 'self-compassion']::text[], '2026-10-12T15:00:00+00:00'::timestamptz),
  ('kind-words-mirror-frame-craft', 'Kind Words Mirror Frame Craft', 'kids'::resource_kind, 'A craft where a child decorates a frame and writes kind words about who they are.', 'Use it to help a child build a kind voice about themselves.', array['Children']::text[], '35 minutes', 'The child decorates a frame with words about who they are, such as brave or funny. Avoid words about looks. The parent writes words they see in their child too. Hang it where the child will see it.', '[{"id": "f0", "type": "textarea", "label": "Words about who I am"}, {"id": "f1", "type": "textarea", "label": "Words my family sees in me"}, {"id": "f2", "type": "textarea", "label": "My favorite thing to do"}, {"id": "f3", "type": "textarea", "label": "Where I will hang my frame"}]'::jsonb, array['body image', 'children', 'art', 'self-esteem']::text[], '2026-10-12T15:00:00+00:00'::timestamptz)
